const enhancements = {

'8-2': {
  addMinutes: 35,
  sections: [
    { type: 'workshop', tag: 'BROWSER', title: 'Workshop A — MCP Architecture Mapping Drill', content: 'Build a concrete mental model of MCP\'s client-server architecture in 8 minutes.\n\n**Step 1 — Draw the architecture** (on paper or in a drawing tool):\n- A box labeled "Claude Code" (the client)\n- Multiple boxes for MCP servers (GitHub, filesystem, database)\n- Arrows showing: Claude sends requests → servers execute → servers return results\n\n**Step 2 — Ask Claude.ai** to validate your diagram: "I drew this diagram of MCP architecture: [describe it]. Is this accurate? What did I get wrong or miss?"\n\n**Step 3 — Ask these specific questions** to test your understanding:\n- "What is the transport layer and what options does MCP support?"\n- "When Claude Code sends a request to an MCP server, what format does the message use?"\n- "Can an MCP server connect to multiple clients simultaneously?"\n\n**Step 4 — Update your diagram** based on what you learned.\n\n**Step 5 — Compare MCP to a REST API:** Ask Claude: "What are the key differences between MCP and a REST API? Why was a new protocol needed?"' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop B — Design an MCP Server for Your Workflow', content: 'Before building anything, design an MCP server that would genuinely help your work.\n\n**Step 1 — List your most time-consuming manual tasks** that require switching between Claude and other tools: looking up documentation, checking databases, reading files in specific formats.\n\n**Step 2 — For your top pain point**, design an MCP server concept:\n- What data source does it connect to?\n- What 3-5 tools would it expose to Claude?\n- What would each tool accept as input and return as output?\n\n**Step 3 — Ask Claude:** *"I\'m designing an MCP server for [your pain point]. Here\'s my concept: [describe it]. Is this a valid use case for MCP? What tools should I expose? What are the security considerations?"*\n\n**Step 4 — Refine your design** based on Claude\'s feedback.\n\n**Step 5 — Mandatory review:** Ask Claude: *"Review this MCP server design. Find 3 potential problems: security risks, tools that would be hard to implement, or capabilities that already exist in standard MCP servers I could use instead."*' },

    { type: 'workshop', tag: 'BROWSER', title: 'Workshop C — MCP vs Direct API Integration', content: 'Understand when MCP is the right choice vs direct API integration.\n\n**Step 1 — Ask Claude:** *"Compare these approaches for giving Claude Code access to GitHub: (1) MCP GitHub server, (2) having Claude Code use the GitHub CLI (gh command), (3) having Claude Code use curl to call GitHub API directly. What are the pros and cons of each?"*\n\n**Step 2 — Read the comparison.** When would each approach be better?\n\n**Step 3 — Ask about the tradeoffs:** "What is the overhead cost of using MCP compared to direct tool use? Are there situations where MCP adds complexity without value?"\n\n**Step 4 — Build your decision framework:**\n| Situation | Use MCP | Use direct tool/CLI | Use API directly |\n|---|---|---|---|\n| Persistent, reusable integration | | | |\n| One-time task | | | |\n| Complex multi-step operations | | | |\n| Simple data retrieval | | | |\n\n**Step 5 — Fill in the table** based on Claude\'s analysis.' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop D — Document the MCP Ecosystem for Your Use Case', content: 'Create a reference document of MCP servers relevant to your specific work.\n\n**Step 1 — Identify your tool ecosystem:** List all the external tools and services you use in your work (GitHub, Slack, Notion, databases, APIs, etc.).\n\n**Step 2 — Ask Claude:** *"For each of these tools, does an official or community MCP server exist? [List your tools]. For each that has one: what tools does it expose, and what would I be able to do with Claude Code that I can\'t do currently?"*\n\n**Step 3 — Research the MCP server registry** (modelcontextprotocol.io or GitHub search for "mcp-server") for any tools Claude didn\'t find.\n\n**Step 4 — Create a reference document:**\n```\n# My MCP Server Landscape\n\n## High Priority (install next)\n- [Tool]: [MCP server name] — enables [capability]\n\n## Medium Priority (useful, not urgent)\n- [Tool]: [MCP server name] — enables [capability]\n\n## No MCP server available\n- [Tool]: use [alternative approach]\n```\n\n**Step 5 — Prioritise and pick one** to install in the next lesson.' },

    { type: 'quiz', question: 'In the MCP architecture, what role does Claude Code play?', options: ['Claude Code is the MCP server that provides tools', 'Claude Code is the MCP client that connects to and uses MCP servers', 'Claude Code is the transport layer between servers', 'Claude Code acts as both client and server simultaneously'], correct: 1, explanation: 'Claude Code is the MCP client — it connects to MCP servers and uses the tools those servers expose. The MCP servers are separate processes (local or remote) that provide specific capabilities: filesystem access, GitHub operations, database queries, etc. Claude Code decides when to call which server based on the task at hand, orchestrating multiple servers in a single conversation.' },

    { type: 'quiz', question: 'An MCP server exposes a tool called `search_documents(query, limit)`. What does exposing this tool mean?', options: ['The tool is automatically called every time Claude Code processes a message', 'Claude Code can discover this tool and call it with arguments when relevant to the task — it returns results that Claude Code uses in its response', 'The tool runs in Claude Code\'s process memory', 'Only the user can call this tool, not Claude Code automatically'], correct: 1, explanation: 'Exposing a tool makes it available in Claude Code\'s tool-use system. Claude Code discovers available tools at the start of a session, decides when a tool is relevant to the current task, calls it with appropriate arguments, receives the result, and incorporates it into its response or next action. It\'s similar to how a person with a calculator uses it selectively — the calculator is available but is called only when calculation is needed.' }
  ]
},

'8-3': {
  addMinutes: 35,
  sections: [
    { type: 'workshop', tag: 'TERMINAL', title: 'Workshop A — Install Your First MCP Server', content: 'This drill gets an MCP server installed and verified in under 8 minutes.\n\n**Step 1 — Choose an MCP server to install.** Recommended for first install:\n- Filesystem MCP (read/write files from Claude Code)\n- GitHub MCP (if you use GitHub)\n- SQLite MCP (if you work with databases)\n\n**Step 2 — Follow the installation steps** for your chosen server:\n\nFor the Filesystem MCP:\n```powershell\nnpm install -g @modelcontextprotocol/server-filesystem\n```\n\n**Step 3 — Configure it in Claude Code\'s settings** (claude_desktop_config.json or Claude Code config file):\n```json\n{\n    "mcpServers": {\n        "filesystem": {\n            "command": "npx",\n            "args": ["-y", "@modelcontextprotocol/server-filesystem", "/path/to/your/project"]\n        }\n    }\n}\n```\n\n**Step 4 — Restart Claude Code** to load the new server.\n\n**Step 5 — Verify:** Ask Claude Code: "What MCP tools do you have available?" — your new server\'s tools should appear.' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop B — Use Your MCP Server for Real Work', content: 'Complete a real task using your newly installed MCP server.\n\n**Step 1 — Open Claude Code** with your MCP server active.\n\n**Step 2 — Give Claude Code a task that requires the MCP server\'s tools:**\n\nFor Filesystem MCP:\n"Search all Python files in my project for any function that takes more than 4 arguments. List each function name, file path, and the number of arguments."\n\nFor GitHub MCP:\n"List all open issues in [your repository] assigned to me. For each, summarise what needs to be done."\n\nFor SQLite MCP:\n"What are the 5 largest tables in my database? Show row counts and column names."\n\n**Step 3 — Watch Claude Code use the MCP tools.** Note which tools it calls and with what arguments.\n\n**Step 4 — Evaluate the result.** Is it accurate? Would this task have been harder without MCP?\n\n**Step 5 — Mandatory review:** Ask Claude Code: *"What could have gone wrong with the MCP tool calls you just made? What data might be wrong or missing?"*' },

    { type: 'workshop', tag: 'BROWSER', title: 'Workshop C — MCP Server Troubleshooting', content: 'MCP servers often fail in predictable ways. This workshop teaches diagnosis.\n\n**Step 1 — Ask Claude:** *"What are the most common reasons an MCP server fails to connect or provides wrong results? For each, describe: (1) the symptom, (2) the likely cause, (3) how to diagnose it, (4) how to fix it."*\n\n**Step 2 — Identify symptoms you\'ve seen** (or might see) in your own MCP setup.\n\n**Step 3 — Practice diagnosis:** If your MCP server is working: ask Claude Code to use a tool in a way that might fail (wrong path, non-existent file, invalid query). What error does it return?\n\n**Step 4 — Ask Claude Code:** "How do I check the logs for MCP server connections? Where do errors appear?"\n\n**Step 5 — Create a troubleshooting reference:** A short list of the 3 most likely failure modes and their fixes for the specific MCP server you installed.' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop D — MCP Server for Your Most-Needed Integration', content: 'Install and configure the MCP server that would deliver the most value for your specific workflow.\n\n**Step 1 — From your MCP landscape document** (Workshop D of 8-2), pick the highest-priority server.\n\n**Step 2 — Install it** following the official documentation.\n\n**Step 3 — Configure access controls.** Most MCP servers need access credentials (API keys, OAuth tokens, file paths). Configure the minimum access needed — don\'t give more permissions than required.\n\n**Step 4 — Test with a real task** from your actual work.\n\n**Step 5 — Mandatory security review:** Ask Claude: *"I just configured this MCP server with these access credentials: [describe what you granted]. What are the security risks? What is the minimum access I actually need?"*\n\n**Step 6 — Document the setup** in your project or personal notes — how to reconfigure if needed.' },

    { type: 'quiz', question: 'You install an MCP server and Claude Code says "I don\'t have access to any MCP tools." What is the most likely cause?', options: ['MCP is not supported in your version of Claude Code', 'The MCP server configuration was not saved to the correct config file or Claude Code was not restarted after adding the configuration', 'You need a paid subscription to use MCP', 'The MCP server needs to be running separately before Claude Code starts'], correct: 1, explanation: 'The most common MCP setup failure: configuration added to the wrong file, or Claude Code not restarted after config changes. Claude Code reads MCP server configurations at startup. Check: (1) the config file path is correct for your OS, (2) the JSON syntax is valid (use a JSON validator), (3) Claude Code was fully restarted (not just a new session, but the actual process). Also verify the command in the config can be run independently in the terminal.' },

    { type: 'quiz', question: 'An MCP filesystem server has access to your entire home directory. What is the principle you should apply when configuring it?', options: ['Give it full access — Claude Code won\'t access files it doesn\'t need', 'Apply least privilege: restrict the MCP server to only the directories Claude Code actually needs to access for your tasks', 'Give it read-only access to everything and write access only to your project folder', 'Use separate MCP servers for different access levels'], correct: 1, explanation: 'Least privilege principle: grant only the minimum access required. For an MCP filesystem server, instead of `/home/user/` (everything), configure it with the specific project paths needed: `/home/user/my-project/`. This limits the blast radius if Claude Code misunderstands a task or a bug causes unexpected file operations. Most MCP servers accept path restrictions in their configuration.' }
  ]
},

'8-4': {
  addMinutes: 35,
  sections: [
    { type: 'workshop', tag: 'BROWSER', title: 'Workshop A — context7 Documentation Drill', content: 'context7 gives Claude Code live documentation for any library. This drill shows why it matters.\n\n**Step 1 — First, test WITHOUT context7.** Ask Claude Code: "Show me how to use the async_timeout context manager in Python\'s asyncio library. Show current syntax with a working example."\n\n**Step 2 — Note the response.** Is the syntax current? Does it reflect the latest Python version\'s recommendations?\n\n**Step 3 — Now enable context7** and ask the same question. Ask Claude Code to use context7 to fetch the current asyncio documentation.\n\n**Step 4 — Compare the two responses.** Did context7 provide more accurate or more current information?\n\n**Step 5 — Test with a library you know well:** Ask Claude Code (with context7) about a specific function in a library where you know the exact correct usage. Does context7 get it right?' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop B — Build with context7 Active Documentation', content: 'Use context7 to build something with a library you\'re less familiar with — and get it right the first time.\n\n**Step 1 — Choose a library you haven\'t used much** but want to use: requests, FastAPI, SQLAlchemy, pandas, OpenAI SDK — something with a specific API.\n\n**Step 2 — Ask Claude Code to build a small program** using that library. Instruct it to use context7 to get current documentation:\n```\nBuild a Python script that [describe your goal] using [library]. Before writing code, use context7 to check the current API for the specific functions you\'ll need.\n```\n\n**Step 3 — Watch Claude Code** fetch documentation through context7. Does it reference the documentation in its response?\n\n**Step 4 — Run the generated code.** Does it work without requiring debugging?\n\n**Step 5 — Mandatory review:** Ask Claude: *"Review the code you just wrote. Which parts are most likely to become outdated as the library releases new versions? What should I check in the docs before using this in production?"*' },

    { type: 'workshop', tag: 'BROWSER', title: 'Workshop C — Verify AI Code with Documentation', content: 'context7 lets you verify that code Claude generates matches current documentation.\n\n**Step 1 — Take any AI-generated code** that uses an external library.\n\n**Step 2 — Ask Claude Code** (with context7): "Verify that this code uses the current API for [library]. Flag any usage that doesn\'t match current documentation."\n\n**Step 3 — Review what context7 finds.** Did the original AI-generated code use deprecated methods or incorrect parameters?\n\n**Step 4 — Update the code** based on the documentation verification.\n\n**Step 5 — Ask Claude:** *"Besides the issues you found, what other common API mistakes do developers make with [library] that I should check for in my code?"*' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop D — Documentation-Driven Development', content: 'Build a feature using a documentation-first approach with context7.\n\n**Step 1 — Choose a feature to implement** that requires a library.\n\n**Step 2 — Start with documentation, not code:**\n```\nBefore writing any code, use context7 to fetch the documentation for [library] and answer:\n1. Which classes/functions will I need for [feature]?\n2. What are the required and optional parameters?\n3. What does the return value look like?\n4. Are there any common gotchas or deprecated patterns to avoid?\n5. Show me the recommended usage pattern from the docs.\n```\n\n**Step 3 — Review the documentation summary.** Do you understand what to build?\n\n**Step 4 — Now write the code** based on the documented patterns. The code should match documentation exactly.\n\n**Step 5 — Compare to the "code first" approach:** Would you have gotten the same result by asking Claude to write the code directly (without documentation lookup first)? Test it and compare.' },

    { type: 'quiz', question: 'Why is context7 useful when Claude Code already has knowledge about popular libraries built into its training?', options: ['Claude Code has no knowledge of any libraries', 'Training knowledge has a cutoff date — context7 provides current documentation, catching API changes, deprecations, and new features released after training', 'context7 makes responses faster', 'Training knowledge is unreliable for all library information'], correct: 1, explanation: 'Even for well-known libraries, AI training data has a cutoff date. Libraries release new versions that change APIs, deprecate methods, and add better patterns. For example, if a library was at version 2.x during training but is now at version 3.x with different APIs, Claude Code will write version 2.x code unless given current documentation. context7 solves this by fetching live, current documentation at the time of the request.' },

    { type: 'quiz', question: 'context7 fetches documentation for a library and Claude Code uses it to generate code. What should you still check before using the code in production?', options: ['Nothing — if it\'s based on current documentation, it\'s correct', 'That the generated code actually follows the documentation correctly — Claude Code can misread or misapply documentation, especially for complex APIs', 'Only check the code if the library is less than 1 year old', 'Whether the library\'s authors are reputable'], correct: 1, explanation: 'Documentation fetching reduces but doesn\'t eliminate errors. Claude Code can still misinterpret documentation, apply patterns from the wrong section, or miss important qualifications in the docs. Verify that: (1) the code uses the methods context7 described, (2) parameters match the documented signatures, (3) any error handling matches what the docs say the library throws. Also run the code against your actual use case — documentation examples often show the happy path only.' }
  ]
},

'8-5': {
  addMinutes: 35,
  sections: [
    { type: 'workshop', tag: 'BROWSER', title: 'Workshop A — Sequential Thinking Drill', content: 'Test how sequential-thinking MCP changes Claude\'s reasoning on a complex problem.\n\n**Step 1 — Choose a genuinely complex problem** from your work — something that requires considering multiple factors and trade-offs.\n\n**Step 2 — Ask Claude WITHOUT sequential thinking** first. Record the response.\n\n**Step 3 — Ask Claude WITH sequential thinking** (or describe the problem and ask Claude to "use sequential, step-by-step structured reasoning where each step explicitly builds on previous ones").\n\n**Step 4 — Compare the responses:**\n- Did sequential thinking surface considerations that the direct response missed?\n- Was the reasoning more transparent and checkable?\n- Did the conclusion differ?\n\n**Step 5 — Identify the types of problems** where sequential structured thinking adds the most value vs when it\'s overkill.' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop B — Apply Sequential Thinking to a Real Decision', content: 'Use sequential thinking to work through a real, complex decision you\'re facing.\n\n**Step 1 — Identify a real decision** you need to make: a technical architecture choice, a project prioritisation decision, a hiring or vendor selection.\n\n**Step 2 — Ask Claude (or Claude Code with sequential-thinking MCP):**\n```\nHelp me think through this decision using sequential, explicit reasoning steps.\n\nDecision: [describe your decision]\nContext: [relevant background]\n\nFor each reasoning step:\n1. State what the step is examining\n2. Present the analysis\n3. Draw an intermediate conclusion\n4. Note any uncertainties or assumptions\n\nEnd with: your recommendation and the one assumption that, if wrong, would change your recommendation.\n```\n\n**Step 3 — Challenge the reasoning** at specific steps where you disagree.\n\n**Step 4 — Mandatory adversarial review:** Ask: *"Play devil\'s advocate on your recommendation. What\'s the strongest argument against it?"*\n\n**Step 5 — Make the decision** based on the full sequential analysis.' },

    { type: 'workshop', tag: 'BROWSER', title: 'Workshop C — Decompose a Complex Task', content: 'Use sequential thinking to break a complex task into executable steps.\n\n**Step 1 — Choose a complex multi-part task** you need to do: implementing a feature, running a research process, coordinating a project.\n\n**Step 2 — Ask Claude to use sequential reasoning to decompose it:**\n```\nBreak down this complex task using sequential thinking:\n\nTask: [describe it]\n\nFor the decomposition:\n- Start with the highest-level goal\n- For each step, identify its dependencies (what must be done first)\n- Flag any steps where the approach depends on an outcome you won\'t know until earlier steps complete\n- Identify the critical path (the sequence that determines the minimum completion time)\n- Note where parallel work is possible\n```\n\n**Step 3 — Review the decomposition.** Is anything in the wrong order? Are dependencies correct?\n\n**Step 4 — Execute the first 2 steps** of the decomposition using Claude Code.\n\n**Step 5 — Reflect:** Did the upfront decomposition make the execution go more smoothly?' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop D — Build a Sequential Thinking Prompt for Your Field', content: 'Create a custom sequential thinking prompt framework tailored to the types of problems you solve.\n\n**Step 1 — Identify the 2-3 types of complex problems** you solve most often at work.\n\n**Step 2 — For each problem type**, ask Claude to design a sequential reasoning framework:\n```\nCreate a sequential thinking framework for this type of problem: [describe problem type].\n\nThe framework should:\n- Define the reasoning steps specific to this problem type\n- Specify what information to gather at each step\n- Define how each step\'s output feeds into the next\n- Include a final synthesis step\n\nFormat it as a reusable prompt template.\n```\n\n**Step 3 — Test each framework** on a real instance of that problem type.\n\n**Step 4 — Refine the frameworks** based on what worked and what missed.\n\n**Step 5 — Save to your prompt library** under "Structured Reasoning Frameworks."' },

    { type: 'quiz', question: 'Sequential thinking MCP has Claude reason through multiple steps before giving an answer. What is the main advantage of this over asking Claude to "think carefully"?', options: ['Sequential thinking is always more accurate than direct answers', 'Sequential thinking makes reasoning explicit and inspectable — you can see each step, identify where it goes wrong, and correct at the specific step rather than rejecting the whole answer', 'Sequential thinking produces longer responses', '"Think carefully" is not a valid prompt instruction'], correct: 1, explanation: 'Making reasoning steps explicit transforms AI thinking from a black box into a transparent process. When reasoning is sequential and explicit: you can check each step independently, identify precisely where the reasoning diverges from your expectations, provide targeted correction at the specific wrong step, and build trust by understanding how the conclusion was reached. "Think carefully" asks for more effort but doesn\'t create inspectable steps.' },

    { type: 'quiz', question: 'You use sequential thinking for a complex analysis. Claude\'s Step 4 conclusion contradicts what you know to be true. What should you do?', options: ['Accept Step 4 and continue — Claude has access to more information', 'Interrupt at Step 4: explain what you know and why it contradicts Step 4, then ask Claude to re-reason from that point with the corrected information', 'Start the whole analysis over with a better prompt', 'Skip Step 4 and continue to Step 5'], correct: 1, explanation: 'Sequential reasoning is designed to be interruptible. If Step 4 is wrong, correct it then: "In Step 4, you concluded X, but I know Y is actually true because Z. Please revise Step 4 with this information and re-derive Steps 5 onwards from the corrected step." This is far more efficient than starting over and ensures your domain knowledge shapes the analysis at the right point.' }
  ]
},

'8-6': {
  addMinutes: 35,
  sections: [
    { type: 'workshop', tag: 'BROWSER', title: 'Workshop A — Actor-Critic Pattern Drill', content: 'Experience the actor-critic pattern on a real task.\n\n**Step 1 — Choose a piece of writing or analysis** you need to produce.\n\n**Step 2 — Run the Actor:** Ask Claude to produce the content.\n\n**Step 3 — Run the Critic immediately:** Without looking at the content\'s quality yourself, ask Claude: *"Act as a harsh, expert critic of the above output. Your job is to find every weakness: logical gaps, unsupported claims, stylistic problems, missing information, and anything that would fail under scrutiny. List specific problems — not general observations."*\n\n**Step 4 — Review the criticism.** Which criticisms do you agree with? Which don\'t apply?\n\n**Step 5 — Run the Actor again** with the criticism in hand: "Revise your output to address criticisms 1, 3, and 5."\n\n**Step 6 — Compare V1 and V2.** How much did the actor-critic loop improve the output?' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop B — Multi-Round Actor-Critic for High-Stakes Work', content: 'Apply the full actor-critic pattern to a piece of genuinely important work.\n\n**Step 1 — Identify a high-stakes document** you need to produce: a proposal, a technical specification, an important email, a report for senior stakeholders.\n\n**Step 2 — Round 1 — Actor:** Ask Claude to draft the document.\n\n**Step 3 — Round 1 — Critic:** Use the actor-critic-thinking MCP tool or this prompt:\n```\nYou are a critical expert in [relevant domain]. Your job is to find flaws in this document. Look for:\n1. Claims that aren\'t supported by evidence\n2. Logic that doesn\'t follow\n3. Important considerations that are missing\n4. Language that could be misunderstood\n5. Anything a hostile audience would challenge\n\nList at least 5 specific problems with the document above.\n```\n\n**Step 4 — Apply the top 3 criticisms.** Revise.\n\n**Step 5 — Round 2 — Different Critic:** Change the critic persona: "Now review this as a lawyer/compliance officer/technical expert" (pick what matters for your audience). Find 3 more problems.\n\n**Step 6 — Final document.** This has been through 2 rounds of adversarial review — it\'s substantially better than a single draft.' },

    { type: 'workshop', tag: 'BROWSER', title: 'Workshop C — Self-Critique as a Habit', content: 'Build self-critique into every AI-assisted task — not just special occasions.\n\n**Step 1 — Create a "self-critique" suffix** you\'ll add to any important prompt:\n```\n[After your response, immediately critique your own output. Identify:\n1. The weakest claim or assumption in your response\n2. What you left out that a thoughtful reader would want\n3. What you would change if you had more information]\n```\n\n**Step 2 — Test it on 3 different prompts** (a writing task, an analysis, a recommendation). Does the self-critique add value?\n\n**Step 3 — Evaluate the self-critique quality.** Does Claude identify real weaknesses or just surface-level issues? For weak self-critiques, push deeper: "Your self-critique was too mild. Find a more fundamental problem with your response."\n\n**Step 4 — Save this suffix** as a toggle you can add to any important prompt.\n\n**Step 5 — Identify the types of tasks** where self-critique adds the most value vs where it\'s unnecessary overhead.' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop D — Build a Quality Review System', content: 'Create a systematic quality review process using the actor-critic pattern for your most important outputs.\n\n**Step 1 — Identify the 2-3 output types** in your work where quality matters most (and errors have real consequences).\n\n**Step 2 — For each output type**, design an actor-critic review protocol:\n- Actor prompt: what to produce and in what format\n- Critic prompt: the specific review criteria for this output type\n- How many rounds of review\n- What triggers a complete restart vs targeted revision\n\n**Step 3 — Ask Claude:** *"Review this actor-critic protocol I\'ve designed [paste it]. Is the critic prompt specific enough to catch real problems? What important review criteria am I missing for [output type]?"*\n\n**Step 4 — Test the protocol** on a real instance of that output type.\n\n**Step 5 — Save the protocol** in your prompt library and commit to using it for every high-stakes output going forward.' },

    { type: 'quiz', question: 'You run the actor-critic pattern and the critic identifies 8 problems. You don\'t have time to address all 8. How should you prioritise?', options: ['Address them in order — the first ones are always most important', 'Ask Claude which 3 criticisms would most significantly impact the quality or reception of the output if left unaddressed', 'Address only the criticisms you already understood and agreed with', 'Address the shortest ones to save time'], correct: 1, explanation: 'Not all criticisms are equal. Ask Claude to rank them by impact: "Which of these 8 criticisms, if not addressed, would most damage the quality, credibility, or effectiveness of this output?" This ensures your limited revision time targets the highest-value improvements. A structural logic flaw is more important than a stylistic concern; a missing key stakeholder argument matters more than phrasing refinement.' },

    { type: 'quiz', question: 'The actor-critic MCP tool automatically generates critique after every response. What is the risk of always applying this critique?', options: ['The critique will always make responses worse', 'Automatic critique can steer toward overly safe, hedged, or committee-designed outputs when sometimes a bold, direct answer is more appropriate', 'The critique takes too long to generate', 'The critique will loop indefinitely'], correct: 1, explanation: 'Systematic critique drives toward comprehensiveness and balance, which is right for formal documents but wrong for a quick direct recommendation, a creative piece, or a situation where confidence is as important as nuance. An auto-critic that always finds "missing perspectives" can turn a decisive answer into a hedged list of considerations. Use the actor-critic pattern deliberately for high-stakes outputs — don\'t let it become a reflex that dilutes every response.' }
  ]
},

'8-7': {
  addMinutes: 35,
  sections: [
    { type: 'workshop', tag: 'BROWSER', title: 'Workshop A — task-master Setup and First Task', content: 'Get task-master-ai running and create your first AI-managed task list.\n\n**Step 1 — Install task-master-ai** (check current installation instructions at the task-master GitHub repo — the package name may have changed).\n\n**Step 2 — Configure it** in your Claude Code MCP settings.\n\n**Step 3 — In Claude Code**, use task-master to create a task list for a real project:\n```\nUsing task-master, create a task list for [your project]. Break it into: tasks I need to do this week, tasks for next week, and backlog. For each task, set a priority (high/medium/low) and estimated time.\n```\n\n**Step 4 — View the created tasks.** Does the structure make sense?\n\n**Step 5 — Mark one task as in-progress.** Ask Claude Code to show you only the in-progress tasks.\n\n**Step 6 — Ask Claude:** *"Compare task-master to using a notes file or Notion for managing tasks. What does task-master add that those can\'t provide?"*' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop B — AI-Driven Project Planning', content: 'Use task-master to break down a real project into manageable tasks with AI guidance.\n\n**Step 1 — Choose a real project** you\'re planning: building a feature, running a research project, completing a work deliverable.\n\n**Step 2 — Ask Claude Code to parse a project description into tasks:**\n```\nUsing task-master, parse this project into tasks:\n\nProject: [describe your project in 2-3 paragraphs]\n\nFor each task:\n- Write a clear, actionable title (starts with a verb)\n- Assign a priority\n- Estimate hours\n- List dependencies (which other tasks must be done first)\n- Assign to a category (Frontend/Backend/Research/Documentation/Testing)\n```\n\n**Step 3 — Review the generated tasks.** What did AI get right? What did it miss or overestimate?\n\n**Step 4 — Mandatory review:** Ask: *"Review the task breakdown. What important tasks did you miss? What tasks are over/underestimated? What dependencies did you not capture?"*\n\n**Step 5 — Update and finalise** the task list. Use it for your actual project.' },

    { type: 'workshop', tag: 'TERMINAL', title: 'Workshop C — Task-Driven Development Session', content: 'Run a complete development session where every action is driven by task-master.\n\n**Step 1 — Open Claude Code** with task-master configured.\n\n**Step 2 — Ask Claude Code which task to work on next:**\n```\nUsing task-master, show me my highest-priority incomplete tasks. Recommend which one I should work on now based on: priority, dependencies (which are already done), and estimated time.\n```\n\n**Step 3 — Accept the recommendation** and work on that task.\n\n**Step 4 — As you work**, ask Claude Code to: update the task status to in-progress, add notes about what you\'re doing, and create subtasks as needed.\n\n**Step 5 — When done**, mark the task complete and ask Claude Code: "What task should I work on next?"\n\n**Step 6 — Reflect:** Did having AI-managed tasks improve your focus vs your normal workflow?' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop D — Integrate task-master with Your Existing Tools', content: 'Connect task-master to your existing project management workflow.\n\n**Step 1 — Identify how you currently track tasks:** Notion, Jira, GitHub Issues, a spreadsheet, a text file.\n\n**Step 2 — Ask Claude:** *"I use [your tool] for task tracking. How can I use task-master alongside it without creating duplication? What should live in task-master vs [your tool]?"*\n\n**Step 3 — Design your integration:**\n- Which tasks go in task-master (AI-assisted, in Claude Code sessions)\n- Which tasks go in your existing tool (team visibility, formal tracking)\n- How will you sync between them?\n\n**Step 4 — Test the workflow** on your current project for one week.\n\n**Step 5 — Evaluate:** After a week, did using task-master improve your AI-assisted development sessions? What would you keep and what would you change?' },

    { type: 'quiz', question: 'task-master-ai manages your project tasks within Claude Code. What is its primary advantage over managing tasks in a separate tool like Jira?', options: ['task-master is always more accurate than Jira', 'Claude Code can read task context and use it to inform its actions — it knows what task you\'re working on and can make decisions accordingly', 'task-master is free and Jira is expensive', 'task-master syncs with all productivity tools automatically'], correct: 1, explanation: 'The key advantage of task-master inside Claude Code is context integration — Claude Code knows what task you\'re working on, can read task descriptions and dependencies, and can use this information to make better decisions. When you say "work on the next highest-priority task," Claude Code knows what that is, reads its description, and starts executing it. External tools (Jira, Notion) don\'t have this tight integration with the AI agent\'s decision-making.' },

    { type: 'quiz', question: 'You use task-master to create 25 tasks for a project. Claude Code always recommends working on the highest-priority task. Is this always the right approach?', options: ['Yes — highest priority should always be done first', 'Not always — sometimes a lower-priority task is the right choice: it unblocks others, it can be done in available time, or the high-priority task requires information you don\'t have yet', 'Claude Code should choose randomly to avoid bias', 'Always work in the order tasks were created'], correct: 1, explanation: 'Priority is one input, not the only input. Good task selection also considers: dependencies (can I actually start this now?), context (am I in the right state to work on this?), time available (do I have 5 minutes or 2 hours?), and momentum (finishing a related task creates flow). Claude Code can help with this nuanced selection if you tell it the full context: "I have 45 minutes and my focus level is low — which task fits?"' }
  ]
},

'8-8': {
  addMinutes: 35,
  sections: [
    { type: 'workshop', tag: 'TERMINAL', title: 'Workshop A — GitHub MCP First Operations', content: 'Get hands-on with GitHub MCP\'s most useful operations.\n\n**Step 1 — Install and configure GitHub MCP** (if not already done from 8-3). You\'ll need a GitHub personal access token.\n\n**Step 2 — In Claude Code**, test these operations on a real GitHub repository you own:\n- "List the 5 most recent open issues in [your repo]"\n- "Show me all pull requests awaiting review"\n- "What was the last commit message and who wrote it?"\n\n**Step 3 — Create an issue via Claude Code:**\n"Create a new GitHub issue in [your repo] titled \'[title]\' with this description: [description]. Label it as a bug."\n\n**Step 4 — Verify the issue was created** by visiting GitHub in your browser.\n\n**Step 5 — Ask Claude Code** to add a comment to the issue you just created: "Add a comment to the issue I just created saying \'Being investigated.\'"\n\n**Step 6 — Rate the experience:** Is this faster than using the GitHub web UI? What operations work best via MCP?' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop B — AI-Assisted PR Review Workflow', content: 'Use GitHub MCP to review pull requests with AI assistance.\n\n**Step 1 — Find an open pull request** in a GitHub repository (your own or one you contribute to).\n\n**Step 2 — Ask Claude Code to review it:**\n```\nReview the open pull request #[number] in [owner/repo]. I want:\n1. Summary of what this PR changes\n2. Any obvious bugs or logic errors in the diff\n3. Missing tests that should be there\n4. Anything that doesn\'t match the project\'s conventions (check CLAUDE.md or README for guidance)\n5. A suggested review comment to post on the most important issue found\n```\n\n**Step 3 — Read Claude Code\'s analysis.** Do you agree? Is anything missing?\n\n**Step 4 — Post a review comment** via Claude Code: "Add a review comment to [PR number] saying: [your comment]."\n\n**Step 5 — Mandatory review of the review:** Ask Claude: *"Review your own PR analysis. What important aspects of a code review did you not check that a senior engineer would look at?"*' },

    { type: 'workshop', tag: 'BROWSER', title: 'Workshop C — GitHub Issue to Implementation Workflow', content: 'Build the workflow from GitHub issue → implementation → PR using Claude Code and GitHub MCP.\n\n**Step 1 — Find or create a GitHub issue** describing a small feature or bug fix.\n\n**Step 2 — Ask Claude Code to read the issue:**\n"Read issue #[number] from [repo]. Summarise the requirement and ask me any clarifying questions before we implement it."\n\n**Step 3 — Answer Claude Code\'s questions** (or say there are none).\n\n**Step 4 — Ask Claude Code to implement the fix:**\n"Implement the fix for issue #[number]. Create a new git branch for this work. After implementation, run the tests."\n\n**Step 5 — Review the implementation.** If it looks right: "Create a draft PR for this implementation. Use the issue description to write the PR body. Link the issue."\n\n**Step 6 — Verify the PR** was created correctly on GitHub.' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop D — GitHub Project Management via Claude Code', content: 'Use GitHub MCP to manage your repository\'s issues and project board without leaving Claude Code.\n\n**Step 1 — Ask Claude Code to audit your GitHub issues:**\n```\nAudit the open issues in [repo]:\n1. List issues that have been open for more than 30 days\n2. List issues with no labels\n3. List issues that are blocking other issues\n4. Which issues should I prioritise this week? (Consider: impact, effort, dependencies)\n```\n\n**Step 2 — Take action on the recommendations:**\n- Add labels to unlabeled issues\n- Close any issues that are no longer valid\n- Add a priority comment to the recommended issues\n\n**Step 3 — Create a sprint plan:** "Create 5 issues for the next sprint based on our backlog, prioritising [your focus area]."\n\n**Step 4 — Evaluate the workflow:** Compare this to using the GitHub web UI. What was faster? What was harder?' },

    { type: 'quiz', question: 'You use GitHub MCP to have Claude Code create a GitHub issue, add labels, and assign it to a milestone — all in one Claude Code session. What is the key risk to verify?', options: ['That Claude Code used the correct API version', 'That all the actions were correctly applied — Claude Code can confirm operations but GitHub is the authoritative source; verify in the GitHub UI', 'That the issue was created in the right timezone', 'That the MCP server is still connected'], correct: 1, explanation: 'When AI systems make changes to external services via APIs, always verify in the authoritative source. GitHub MCP may report success but the actions could have partially failed, applied to the wrong repository, or set wrong values (e.g., wrong milestone ID). After any batch of GitHub operations, open GitHub in your browser and verify the changes are what you expected. This takes 30 seconds and catches silent failures.' },

    { type: 'quiz', question: 'Claude Code uses GitHub MCP to comment on a colleague\'s pull request with review feedback. What should you always do before allowing this?', options: ['Ensure Claude Code has write access to the repository', 'Read and approve the exact text of the comment before Claude Code posts it — comments on others\' work are visible and represent you professionally', 'Ask the colleague for permission first', 'Post it as a draft comment that can be deleted'], correct: 1, explanation: 'Any action that creates publicly visible content under your name requires human review before posting. Code review comments are professional communications — a tone-deaf, inaccurate, or unclear comment reflects on you, not on the AI. Always read exactly what Claude Code will post before it posts it. For GitHub comments specifically: ask Claude Code to draft the comment, review the draft, approve or revise, then post.' }
  ]
},

'8-9': {
  addMinutes: 35,
  sections: [
    { type: 'workshop', tag: 'TERMINAL', title: 'Workshop A — Filesystem MCP Operations Drill', content: 'This drill tests the core operations of the Filesystem MCP.\n\n**Step 1 — Open Claude Code** with Filesystem MCP configured.\n\n**Step 2 — Run these operations on your project folder:**\n- "List all files in the project that were modified in the last 7 days"\n- "Find all Python files that import the requests library"\n- "Read the contents of [specific file] and summarise what it does"\n- "Find all TODO comments in the codebase"\n- "What is the largest file in the project?"\n\n**Step 3 — Verify each result** by checking the actual filesystem (use a terminal or file explorer to confirm).\n\n**Step 4 — Test a write operation:** "Create a file called `analysis.txt` containing a brief summary of this project\'s structure."\n\n**Step 5 — Ask Claude:** "For file navigation tasks, when is Filesystem MCP better than running shell commands directly? When is it worse?"' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop B — Codebase Analysis with Filesystem MCP', content: 'Use Filesystem MCP to analyse a real codebase and extract actionable insights.\n\n**Step 1 — Open Claude Code** with Filesystem MCP on a project you want to understand better.\n\n**Step 2 — Run a comprehensive codebase analysis:**\n```\nUsing the filesystem tools, analyse this codebase:\n1. What are the largest files (by line count)? Large files often need refactoring.\n2. Which directories have the most files? This shows where complexity concentrates.\n3. Are there any duplicate or very similar filenames that might cause confusion?\n4. What file types exist and in what proportions?\n5. Are there any files that look like they might be temporary or should be in .gitignore?\n```\n\n**Step 3 — Review the analysis.** Does it reveal any problems you knew about?\n\n**Step 4 — Ask Claude Code to take action** on one finding: "Based on your analysis, [specific action — e.g., add these file patterns to .gitignore]."\n\n**Step 5 — Mandatory review:** "Review the changes you just made. What else might need to be updated as a result?"' },

    { type: 'workshop', tag: 'BROWSER', title: 'Workshop C — Security Implications of Filesystem Access', content: 'Understand the security considerations of giving Claude Code filesystem access.\n\n**Step 1 — Ask Claude:** *"What are the security risks of giving an AI agent full read/write access to my filesystem? What are the most dangerous operations it could perform?"*\n\n**Step 2 — Review the risks.** Which ones apply to your situation?\n\n**Step 3 — Ask for mitigation strategies:** "For each risk you identified, what is the mitigation? How do I configure Filesystem MCP to minimize these risks?"\n\n**Step 4 — Audit your current Filesystem MCP configuration:**\n- What paths does it have access to?\n- Does it have write access? Should it?\n- Are sensitive files (credentials, private keys) in accessible paths?\n\n**Step 5 — Implement one security improvement** to your Filesystem MCP configuration.' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop D — Automated File Organisation', content: 'Use Filesystem MCP to create an automated file organisation system.\n\n**Step 1 — Choose a messy directory** in your file system — a downloads folder, a project folder with mixed file types, a notes directory.\n\n**Step 2 — Ask Claude Code to analyse and propose an organisation:**\n```\nAnalyse the files in [directory]. Propose an organisation system that would:\n1. Group related files\n2. Create a clear naming convention\n3. Separate work-in-progress from completed files\n4. Handle the most common file types I have\n\nBefore moving anything, describe the proposed structure and what rules you\'ll follow.\n```\n\n**Step 3 — Review the proposal.** Does the logic make sense?\n\n**Step 4 — Ask Claude Code to implement it** in a test subdirectory first: "Create a sample of the proposed structure with 5 representative files to show me how it will look."\n\n**Step 5 — Approve and execute** the full reorganisation after reviewing the sample.' },

    { type: 'quiz', question: 'You give Filesystem MCP write access to your entire home directory. Claude Code deletes files it identified as "temporary" that you actually needed. How should you have prevented this?', options: ['Never give Claude Code write access', 'Restrict write access to specific project directories and require confirmation before any deletion', 'Only use Filesystem MCP in read-only mode', 'Keep a manual backup before every Claude Code session'], correct: 1, explanation: 'Restrict write access to specific directories only, and for destructive operations (delete, overwrite), configure your Claude Code CLAUDE.md or hooks to require explicit confirmation. Deletion is irreversible — treat it as a high-risk operation regardless of how confident the AI seems. The minimum safe configuration: read-only on most paths, write access only to the current project directory, and no delete capability without confirmation.' },

    { type: 'quiz', question: 'Filesystem MCP can read any file in the directories you\'ve configured. What types of files should you ensure are OUTSIDE the configured directories?', options: ['Large files that would slow down reading', 'API keys, passwords, private SSH keys, and other secrets — these should never be in Claude Code\'s readable paths', 'Binary files that AI can\'t interpret', 'Files owned by other users'], correct: 1, explanation: 'The biggest security risk of filesystem access is secrets exposure. Any file readable by Filesystem MCP could be included in Claude Code\'s context and potentially expose credentials. Ensure these are outside configured paths: .env files with API keys, SSH private keys (~/.ssh/), browser credential stores, password manager databases, and any other secrets. Use environment variables for credentials that Claude Code needs, not files in the accessible directory tree.' }
  ]
},

'8-10': {
  addMinutes: 35,
  sections: [
    { type: 'workshop', tag: 'BROWSER', title: 'Workshop A — Browser MCP Capabilities Tour', content: 'Explore what the Playwright/Browser MCP can do in 8 minutes.\n\n**Step 1 — Configure Browser MCP** (Playwright MCP) in your Claude Code settings.\n\n**Step 2 — Test basic navigation:**\n- "Open a browser and navigate to example.com"\n- "Take a screenshot of the current page"\n- "What links are on this page?"\n\n**Step 3 — Test form interaction:**\n- "Navigate to a simple form page and fill in the name field with \'Test User\'"\n\n**Step 4 — Test content extraction:**\n- "Navigate to [a public webpage relevant to your work] and extract all the key data points from the main content"\n\n**Step 5 — Ask Claude:** "What types of web automation tasks are best suited to Browser MCP? What should I use a different approach for (e.g., direct API calls vs browser automation)?"' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop B — Automate a Real Web Task', content: 'Use Browser MCP to automate a real, recurring web task you currently do manually.\n\n**Step 1 — Identify a web task you do manually at least weekly:** Checking a dashboard, filling out a form, copying data from a web table, monitoring a webpage for changes.\n\n**Step 2 — Describe the task** to Claude Code in detail: URL, what you look for, what you do with the information.\n\n**Step 3 — Ask Claude Code to automate it using Browser MCP:**\n```\nAutomate this web task using browser control:\nTask: [describe it]\nStart at: [URL]\nFor each step, describe what you\'re doing so I can follow along.\n```\n\n**Step 4 — Watch the automation execute.** Note: which steps does it handle correctly, and which require human judgement?\n\n**Step 5 — Evaluate:** How much time does this automation save per occurrence? Is it reliable enough to run without supervision?' },

    { type: 'workshop', tag: 'BROWSER', title: 'Workshop C — Web Scraping with Browser MCP', content: 'Use Browser MCP for ethical data collection from websites.\n\n**Step 1 — Choose a public website** with data you regularly need: job listings, news headlines, competitor pricing (public), event calendars.\n\n**Step 2 — Check the legal and ethical considerations** first: Ask Claude: "Is scraping [website] for [purpose] legal and ethical? What should I check before proceeding?"\n\n**Step 3 — If appropriate, design the extraction:**\n```\nNavigate to [URL] and extract:\n- [Data field 1]: [where it appears on the page]\n- [Data field 2]: [where it appears]\nFormat the output as a CSV table.\n```\n\n**Step 4 — Run the extraction.** Is the data accurate? Is the format useful?\n\n**Step 5 — Consider alternatives:** For sites with public APIs, direct API calls are more reliable and more polite than browser scraping. Ask Claude: "Does [website] have a public API that would be better than browser scraping for this data?"' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop D — Build an Automated Testing Script', content: 'Use Browser MCP to automate testing of a web application.\n\n**Step 1 — Choose a web application** you\'re building or maintaining.\n\n**Step 2 — Identify the 3 most important user flows** to test: login, key feature, checkout, etc.\n\n**Step 3 — Ask Claude Code to create test scenarios:**\n```\nCreate browser automation test scenarios for these user flows in [application name]:\n1. [Flow 1]: [describe expected behaviour]\n2. [Flow 2]: [describe expected behaviour]\n3. [Flow 3]: [describe expected behaviour]\n\nFor each test: describe the steps, what to verify, and what failure looks like.\n```\n\n**Step 4 — Execute one test scenario** using Browser MCP.\n\n**Step 5 — Mandatory review:** Ask Claude: *"Review the test scenario you executed. What important user behaviour did you not test? What edge cases might break this flow that the test didn\'t cover?"*' },

    { type: 'quiz', question: 'Browser MCP gives Claude Code control of a real browser. What is the most important safety consideration before using it on websites requiring login?', options: ['Browser speed — logged-in sessions are slower to automate', 'That Claude Code will be operating as you — any action it takes (posting, purchasing, deleting) happens under your account with real consequences', 'Browser MCP does not support login flows', 'You must use incognito mode for all Browser MCP sessions'], correct: 1, explanation: 'When Claude Code controls a logged-in browser session, it acts as you — with your permissions, your account, your data. Mistakes are real: if it accidentally posts publicly, purchases something, or deletes data, those consequences are real. For any browser automation on authenticated sessions: review exactly what Claude Code will do before it does it, and avoid browser automation for any irreversible actions (purchases, posts, deletions) without explicit step-by-step confirmation.' },

    { type: 'quiz', question: 'You ask Claude Code to use Browser MCP to fill out and submit a form on a third-party website. Before submitting, what must you verify?', options: ['That the form field names match what Claude Code is using', 'That the data being submitted is exactly what you intend — review each field value before submission, as form submission is typically irreversible', 'That the website uses HTTPS', 'That the form doesn\'t have CAPTCHA protection'], correct: 1, explanation: 'Form submission is often irreversible — you can\'t un-submit a job application, un-register for an event, or un-send a contact form. Before submitting, ask Claude Code to: "List all the form field values you\'re about to submit." Read every value, verify it\'s correct, and only then confirm submission. Treat browser form submission the same way you\'d treat a financial transaction — verify before confirming.' }
  ]
},

'8-12': {
  addMinutes: 35,
  sections: [
    { type: 'workshop', tag: 'TERMINAL', title: 'Workshop A — Google Drive MCP Operations', content: 'Hands-on with Google Drive MCP in 8 minutes.\n\n**Step 1 — Configure Google Drive MCP** with appropriate OAuth credentials.\n\n**Step 2 — Test these operations:**\n- "List the 10 most recently modified files in my Google Drive"\n- "Search for files with \'budget\' in the name"\n- "Read the contents of [specific document name]"\n\n**Step 3 — Test search with context:** "Find all Google Docs that mention [a specific topic related to your work] and list their titles and last modified dates."\n\n**Step 4 — Test Calendar:** "What meetings do I have tomorrow? For each, show the title and time."\n\n**Step 5 — Evaluate:** What is the most immediately useful operation for your workflow? What is harder than expected?' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop B — AI Meeting Prep from Calendar', content: 'Use Google Calendar MCP to automatically prepare for upcoming meetings.\n\n**Step 1 — Open Claude Code** with Google Calendar MCP.\n\n**Step 2 — Run a meeting preparation workflow:**\n```\nCheck my Google Calendar for today and tomorrow. For each meeting:\n1. Identify the topic/purpose from the event title\n2. Note who the attendees are\n3. Suggest 3 preparation questions I should be able to answer\n4. If there\'s a document or email about this topic in my Drive, find it\n```\n\n**Step 3 — Review the preparation brief.** Is it useful? What context is missing?\n\n**Step 4 — For your next real meeting**, actually use this preparation brief before attending. Did it help?\n\n**Step 5 — Mandatory review:** Ask Claude: *"Review the meeting prep brief. What important preparation is missing? What questions should I ask myself that you didn\'t generate?"*' },

    { type: 'workshop', tag: 'BROWSER', title: 'Workshop C — Drive Document Analysis', content: 'Use Google Drive MCP to analyse documents across your Drive.\n\n**Step 1 — Ask Claude Code** to identify documents that need attention:\n```\nSearch my Google Drive for:\n1. Documents that haven\'t been modified in over 6 months but have "current" or "active" in their name\n2. Duplicate or similar document names that might represent redundant files\n3. Large folders that might be disorganised\n```\n\n**Step 2 — Review the findings.** Do they surface real organisational problems?\n\n**Step 3 — Choose one finding** and take action: archive a stale document, rename a misleading one, or reorganise a folder.\n\n**Step 4 — Ask Claude:** *"Based on what you found in my Drive, what organisational principles would you recommend I adopt for naming and organising documents going forward?"*\n\n**Step 5 — Write a one-page Drive organisation guide** for yourself.' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop D — Weekly Review Workflow', content: 'Build an automated weekly review using Calendar and Drive MCP.\n\n**Step 1 — Design your weekly review:**\n- What did I accomplish this week? (from calendar and Drive activity)\n- What meetings do I have next week? (from calendar)\n- What documents need attention? (from Drive search)\n- What are my priorities for next week?\n\n**Step 2 — Create a custom slash command** `review-week.md` in your `.claude/commands/` folder that executes this workflow.\n\n**Step 3 — Test the command** at the end of your current workweek.\n\n**Step 4 — Evaluate:** How much time does the AI-assisted weekly review save vs doing it manually? What does the AI miss that requires your personal knowledge?\n\n**Step 5 — Refine the command** based on what you found most and least useful.' },

    { type: 'quiz', question: 'Google Drive MCP can read your Google Docs. You ask Claude Code to summarise all documents in your "Projects" folder. What is an important risk?', options: ['Claude Code may not handle Google Docs format correctly', 'The summary will include all document contents in Claude Code\'s context — if any documents contain sensitive information, it will be processed by Anthropic\'s systems', 'The summarisation will delete the original documents', 'Claude Code cannot access shared documents'], correct: 1, explanation: 'When Claude Code reads your Google Drive documents, the content is processed through Anthropic\'s API. If your documents contain sensitive business information, client data, personal information, or confidential content, this is sent to Anthropic\'s cloud. Review your organisation\'s data policies and Claude\'s data retention policies before using Drive MCP on sensitive documents. Consider configuring it with access only to specific, non-sensitive folders.' },

    { type: 'quiz', question: 'You use Calendar MCP and Claude Code creates a new calendar event on your behalf. Who is responsible for verifying the event details are correct?', options: ['The MCP server, which validates all calendar entries', 'You — Claude Code may create events with incorrect times, wrong attendees, or inaccurate descriptions; always verify before the event', 'Google Calendar, which auto-corrects AI-created events', 'Claude Code confirms with you before creating any event'], correct: 1, explanation: 'Any AI-created calendar event requires your verification. Common failure modes: wrong time zone (especially for remote participants), including wrong attendees (common names, similar email addresses), inaccurate meeting description, setting the wrong meeting duration. After any calendar creation via MCP, open Google Calendar and verify the event details before other attendees receive invitations. Incorrect meeting invitations are a real professional embarrassment.' }
  ]
},

'8-13': {
  addMinutes: 35,
  sections: [
    { type: 'workshop', tag: 'TERMINAL', title: 'Workshop A — SQLite MCP First Queries', content: 'This drill gets you running real SQL queries via Claude Code.\n\n**Step 1 — Set up a SQLite database** for testing:\n```powershell\n# Create a test database using Python\npython -c "import sqlite3; conn = sqlite3.connect(\'test.db\'); c = conn.cursor(); c.execute(\'CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, name TEXT, email TEXT, created_at TEXT)\'); c.executemany(\'INSERT INTO users VALUES (?,?,?,?)\', [(1,\'Alice\',\'alice@example.com\',\'2024-01-15\'),(2,\'Bob\',\'bob@example.com\',\'2024-02-20\'),(3,\'Carol\',\'carol@example.com\',\'2024-03-10\')]); conn.commit()"\n```\n\n**Step 2 — Configure SQLite MCP** to point to test.db.\n\n**Step 3 — In Claude Code**, run these queries:\n- "List all tables in the database"\n- "Show the schema for the users table"\n- "Count how many users were created each month"\n- "Find any users with duplicate email addresses"\n\n**Step 4 — Ask Claude to write a query you don\'t know how to write:** "Find the users who were created most recently in each month."\n\n**Step 5 — Verify all queries** return correct results.' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop B — Real Database Analysis', content: 'Use SQLite MCP to analyse a real database from your work.\n\n**Step 1 — Identify a real SQLite database** from your work (or create a small one from CSV data you have).\n\n**Step 2 — Run a comprehensive database analysis:**\n```\nAnalyse this database:\n1. List all tables with their row counts\n2. For each table, describe what it likely contains based on the schema\n3. Identify foreign key relationships (even if not formally declared)\n4. Find any tables that seem to have data quality issues (nulls, duplicates, anomalies)\n5. What are the 3 most important business questions this database could answer?\n```\n\n**Step 3 — Ask the most important question** from Claude\'s analysis.\n\n**Step 4 — Mandatory review:** Ask: *"Review your analysis. What assumptions did you make about the data that might be wrong? What would you need to verify to be confident in these findings?"*\n\n**Step 5 — Create a one-page database documentation** based on Claude\'s analysis.' },

    { type: 'workshop', tag: 'TERMINAL', title: 'Workshop C — Safe Database Operations', content: 'Practice running database operations with appropriate safety measures.\n\n**Step 1 — Understand the risk tiers:**\n- **Safe**: SELECT queries — read-only, no risk\n- **Careful**: INSERT, UPDATE — adds or changes data\n- **Dangerous**: DELETE, DROP — removes data permanently\n\n**Step 2 — For any write operation**, always use this workflow:\n1. Run a SELECT to see what you\'re about to change\n2. Verify the WHERE clause would target exactly the right rows\n3. Then run the write operation\n\n**Step 3 — Practice the pattern:**\n```\n-- First: see what you\'re about to update\nSELECT * FROM users WHERE created_at < \'2024-01-01\';\n-- Review the rows, then:\nUPDATE users SET status = \'archived\' WHERE created_at < \'2024-01-01\';\n```\n\n**Step 4 — Ask Claude Code** to run an UPDATE on your test database using this workflow.\n\n**Step 5 — Ask Claude:** "What database safety practices should I configure in CLAUDE.md to prevent Claude Code from running destructive database operations without confirmation?"' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop D — AI-Generated SQL Reporting', content: 'Use Claude Code with SQLite MCP to generate automated data reports.\n\n**Step 1 — Choose a reporting question** you regularly need answered from your data.\n\n**Step 2 — Ask Claude Code to write and run the report:**\n```\nGenerate a report answering: [your question]\n\nFor the report:\n1. Write the SQL query\n2. Explain what the query does before running it\n3. Run the query\n4. Interpret the results: what do the numbers mean?\n5. What follow-up questions do the results raise?\n```\n\n**Step 3 — Review the SQL** before Claude Code runs it.\n\n**Step 4 — Validate the results** against what you expect or can manually verify.\n\n**Step 5 — Save the query** in a queries library for reuse. Ask Claude to format it with comments explaining each part.' },

    { type: 'quiz', question: 'Claude Code generates this SQL: `DELETE FROM users WHERE last_login < \'2023-01-01\'`. Before executing it, what must you do?', options: ['Check if the database is backed up', 'Run `SELECT * FROM users WHERE last_login < \'2023-01-01\'` first to see exactly which rows will be deleted and verify this is your intent', 'Verify the SQL syntax is correct', 'Ask Claude Code if it\'s sure about the query'], correct: 1, explanation: 'Before any DELETE: always SELECT first with the same WHERE clause to see exactly what will be affected. This is the professional safety protocol. Even if Claude Code correctly understood your request, verify: are there really that many rows? Are any of these IDs in use in other tables? Is the date threshold right? A DELETE with no backup and no prior SELECT check is one of the most common paths to irreversible data loss.' },

    { type: 'quiz', question: 'Claude Code writes an SQL query with a JOIN between tables and tells you it represents "all active users who made a purchase in 2024." Why might this still need verification?', options: ['Claude Code SQL is always correct', 'The JOIN logic might not match your database\'s actual foreign key structure, or "active" might be defined differently in your schema than Claude Code assumed', 'SQL JOINs are automatically validated by the database', 'The query will error if it\'s wrong, so errors will catch any issues'], correct: 1, explanation: 'Claude Code makes assumptions about schema relationships that may not match your actual data model. "Active users" might mean different things in different schemas (status = \'active\', is_deleted = false, last_login within 30 days). The JOIN might use wrong column names or miss a required condition. Always check: does the WHERE clause match your actual definition? Does the row count make sense? Run with a LIMIT first on large tables.' }
  ]
},

'8-14': {
  addMinutes: 35,
  sections: [
    { type: 'workshop', tag: 'BROWSER', title: 'Workshop A — MCP Registry Exploration', content: 'Explore the MCP ecosystem to find servers for your specific needs.\n\n**Step 1 — Visit the main MCP directories:**\n- modelcontextprotocol.io (official)\n- GitHub: search "mcp-server" and filter by recent activity\n- Awesome MCP list (search GitHub for "awesome-mcp")\n\n**Step 2 — For your top 3 daily tools** (Slack, Notion, Jira, Salesforce, etc.), search for MCP servers.\n\n**Step 3 — For each server found**, evaluate:\n- Stars (popularity proxy)\n- Last commit (is it maintained?)\n- Issues open/closed ratio (actively supported?)\n- License (can you use it in your context?)\n\n**Step 4 — Ask Claude:** *"How do I evaluate the quality and safety of a community MCP server before installing it? What red flags should make me avoid a server?"*\n\n**Step 5 — Shortlist 2 servers** to try next.' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop B — Evaluate and Install a Community MCP Server', content: 'Apply a rigorous evaluation process before installing a community MCP server.\n\n**Step 1 — Choose a community MCP server** from your shortlist.\n\n**Step 2 — Security evaluation before installation:**\n- Read the source code (if open source) — what data does it access? What does it send where?\n- Check the npm/pip package for known vulnerabilities\n- Verify the publisher is reputable\n- Read all permissions it requests\n\n**Step 3 — Ask Claude:** *"I found this MCP server: [describe it, paste its README]. What security risks should I evaluate before installing? What questions should I ask the maintainer?"*\n\n**Step 4 — Install in a test environment first** (not your production setup).\n\n**Step 5 — Test with minimal permissions** initially — don\'t grant full access on the first run. Verify it works, then grant additional permissions if needed.' },

    { type: 'workshop', tag: 'BROWSER', title: 'Workshop C — Build a Personal MCP Server Catalogue', content: 'Maintain a curated catalogue of MCP servers that are vetted and useful for your work.\n\n**Step 1 — Create a document** called `mcp-catalogue.md` in your project or personal notes.\n\n**Step 2 — Document each MCP server you use or evaluate:**\n```\n## [Server Name]\n**Package**: [npm/pip name]\n**Purpose**: [what it does]\n**Tools**: [list of exposed tools]\n**Access required**: [what credentials/permissions it needs]\n**Risk level**: [low/medium/high] and why\n**Status**: [installed/evaluating/rejected] and why\n**Last verified**: [date]\n```\n\n**Step 3 — Add 5 entries** for servers you\'ve used or evaluated in this course.\n\n**Step 4 — Ask Claude:** *"Review my MCP catalogue entries. What important information am I missing that would help me or a colleague make installation decisions?"*\n\n**Step 5 — Share the catalogue** with any colleagues who also use Claude Code.' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop D — Design a Custom MCP Server Specification', content: 'Specify a custom MCP server you would build for your own needs.\n\n**Step 1 — Identify your highest-value unsupported integration** — a tool or data source you use that has no good existing MCP server.\n\n**Step 2 — Design the server specification:**\n```\nServer name: [name]-mcp\nPurpose: [what problem it solves]\n\nTools (each with name, description, parameters, return format):\n1. [tool_name]: [what it does]\n   Parameters: [param: type, description]\n   Returns: [format]\n\n2. [tool_name]: ...\n\nAuthentication: [how it authenticates with the backing service]\nSecurity considerations: [what access it needs, what risks exist]\n```\n\n**Step 3 — Ask Claude to review the specification:** *"Review this MCP server specification. What tools are missing? What parameter designs are incorrect or could be improved? What security issues haven\'t I addressed?"*\n\n**Step 4 — Refine the specification** based on Claude\'s feedback.\n\n**Step 5 — Save the specification** — you\'ll build a version of this in Lesson 8-15.' },

    { type: 'quiz', question: 'You find an MCP server on GitHub with 5 stars, last commit 2 years ago, and 15 open issues. Should you install it?', options: ['Yes — any MCP server that works is worth using', 'Proceed with caution: low activity and unresolved issues suggest it may be unmaintained, potentially broken with current Claude Code versions, or missing security fixes', 'No — you should only use official MCP servers', 'Yes — old code is more stable than new code'], correct: 1, explanation: 'Low stars, old commits, and unresolved issues are yellow flags, not automatic disqualifiers. Investigate: do any open issues report security vulnerabilities or broken functionality? Is the 2-year-old code still compatible with current Claude Code? Sometimes a small, stable server is maintained exactly as-is intentionally. But these signals warrant careful evaluation before installation, especially if the server requires sensitive credentials.' },

    { type: 'quiz', question: 'A community MCP server requests access to your GitHub token, Slack workspace, and email credentials simultaneously. What is the appropriate response?', options: ['Grant all access — this is how MCP servers work', 'Grant only the minimum permissions actually needed for your use case, evaluate why it needs all three, and consider whether a server combining this much access is a higher risk than individual servers', 'Refuse and only use official MCP servers', 'Grant access temporarily and revoke it after each session'], correct: 1, explanation: 'A single MCP server with broad cross-service access is a higher-risk configuration — if it\'s compromised or has a bug, it could affect multiple services. Evaluate: does your use case actually require all three services together in a single server? Could you use separate, more focused servers for each? If you do grant access, use minimal-permission tokens (read-only where possible), and monitor the server\'s behaviour carefully during the first few sessions.' }
  ]
},

'8-15': {
  addMinutes: 40,
  sections: [
    { type: 'workshop', tag: 'BUILD', title: 'Workshop A — Plan Your Custom MCP Server', content: 'Design your custom MCP server before writing any code.\n\n**Step 1 — Review your server specification** from Lesson 8-14 Workshop D.\n\n**Step 2 — Ask Claude to refine the design:**\n```\nI want to build an MCP server. Here is my specification: [paste it]\n\nHelp me finalize the design:\n1. Review each tool for correct input/output format\n2. Identify any tools that should be split or merged\n3. Design the error handling strategy\n4. Recommend the implementation language (Python or TypeScript) for my use case\n5. Identify the external library/API I\'ll need\n```\n\n**Step 3 — Choose your implementation language** based on Claude\'s recommendation and your experience.\n\n**Step 4 — Create the project structure:**\n```\nmcp-server-[name]/\n  src/\n    server.py (or index.ts)\n  tests/\n  README.md\n  requirements.txt (or package.json)\n```\n\n**Step 5 — Write a README first** — describe what the server does before any code exists.' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop B — Build the Core MCP Server', content: 'Implement your MCP server with Claude Code\'s assistance.\n\n**Step 1 — Ask Claude Code to scaffold the server:**\n```\nBuild an MCP server in Python using the mcp package. The server should:\n- Expose these tools: [list your tools with descriptions]\n- Authenticate with: [your API/service]\n- Handle errors by: [your error strategy]\n\nStart with the basic structure and the first tool implemented. I\'ll review each tool before we add the next.\n```\n\n**Step 2 — Review the scaffolded structure** before adding tools.\n\n**Step 3 — Implement tools one at a time.** For each tool:\n- Ask Claude Code to implement it\n- Review the code\n- Test it manually\n- Fix any issues before moving to the next\n\n**Step 4 — Mandatory code review after each tool:** *"Review the [tool name] implementation. Find 3 potential failure modes: edge cases, API errors, or unexpected inputs that would break this tool."* Fix the issues found.' },

    { type: 'workshop', tag: 'TERMINAL', title: 'Workshop C — Test Your MCP Server', content: 'Write and run tests for your custom MCP server.\n\n**Step 1 — Ask Claude Code to write tests:**\n```\nWrite a test file for this MCP server. For each tool:\n1. A happy path test (valid input, expected output)\n2. An error case test (invalid input or API failure)\n3. An edge case test (boundary values, empty input)\n\nUse pytest and mock the external API calls.\n```\n\n**Step 2 — Run the tests:**\n```powershell\npython -m pytest tests/ -v\n```\n\n**Step 3 — Fix any test failures** with Claude Code\'s help.\n\n**Step 4 — Add error handling tests** for cases Claude Code might have missed:\n- What happens if the external service is down?\n- What happens with a malformed response?\n- What happens with a very large input?\n\n**Step 5 — Mandatory review:** Ask: *"Review the test coverage. What important scenarios are NOT tested that a code reviewer would flag?"*' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop D — Integrate and Use Your MCP Server', content: 'Complete the full cycle: build → test → integrate → use.\n\n**Step 1 — Configure your server** in Claude Code\'s MCP settings.\n\n**Step 2 — Restart Claude Code** to load your new server.\n\n**Step 3 — Verify discovery:** Ask Claude Code: "What MCP tools do you have available?" — your custom tools should appear.\n\n**Step 4 — Run a real task** using your new server: "Use [your tool name] to [actual task your server enables]."\n\n**Step 5 — Mandatory real-world review:** Run the task and verify the output is correct and useful. Is the server doing what you designed it to do?\n\n**Step 6 — Document the lessons learned:** What did you have to change from your original design? What would you do differently?\n\n**Step 7 — Share your server** with colleagues if it solves a shared problem.' },

    { type: 'quiz', question: 'Your custom MCP server successfully connects but returns wrong data for one tool. What is the debugging approach?', options: ['Rewrite the entire server', 'Add logging to the specific tool\'s implementation to trace what API call is made and what response is received, then identify where the transformation goes wrong', 'Ask Claude Code to fix it without adding any logging', 'Mark that tool as broken and don\'t use it'], correct: 1, explanation: 'Debugging a single failing tool requires tracing the data flow: what input did Claude Code send → what API call was made → what did the API return → how was it transformed into the output. Add log statements at each step (or use Python\'s logging module). Once you can see the actual API response vs what you expected, the bug location becomes obvious. This is the same debugging approach for any integration code.' },

    { type: 'quiz', question: 'You build an MCP server that stores credentials in a plain text config file. What is the security problem and fix?', options: ['Plain text is fine if the file has restricted permissions', 'Plain text credentials can be accidentally committed to git, logged, or read by malicious software — use environment variables or a secrets manager instead', 'Credentials should be in the server code itself, not a config file', 'MCP servers don\'t need credentials'], correct: 1, explanation: 'Plain text credentials in files are a major security risk: they may be accidentally committed to version control (a very common incident), included in backup files, or read by other processes. The correct approach: use environment variables (the credentials are never stored in files at all), or use a secrets manager (AWS Secrets Manager, 1Password, etc.) that requires authentication to access credentials. Add the config file with credentials to .gitignore immediately.' }
  ]
},

'8-16': {
  addMinutes: 35,
  sections: [
    { type: 'workshop', tag: 'TERMINAL', title: 'Workshop A — Outlook MCP First Operations', content: 'Get hands-on with Outlook MCP\'s core capabilities.\n\n**Step 1 — Configure Outlook MCP** with Microsoft Graph API credentials.\n\n**Step 2 — Test core operations in Claude Code:**\n- "List my 5 most recent unread emails with sender, subject, and date"\n- "Show me emails from [person] in the last 7 days"\n- "Search for emails with \'invoice\' in the subject from the last month"\n\n**Step 3 — Test draft creation:**\n"Draft an email to [your own address] with subject \'MCP Test\' and body \'This email was drafted by Claude Code via Outlook MCP.\'"\n\n**Step 4 — Verify the draft** exists in Outlook before sending anything.\n\n**Step 5 — Ask Claude:** "What are the most valuable email operations I should use Outlook MCP for in my workflow? What should I NOT use it for?"' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop B — AI Email Triage Workflow', content: 'Build an AI-powered email triage workflow using Outlook MCP.\n\n**Step 1 — Ask Claude Code to process your recent emails:**\n```\nCheck my recent emails (last 2 days). For each unread email:\n1. Categorise it: Action required / FYI / Newsletter / Other\n2. For "Action required": what specifically do I need to do?\n3. Priority: High (deadline today/tomorrow) / Medium / Low\n4. Suggested response time: Today / This week / Not urgent\n\nDon\'t take any action — just give me the triage summary.\n```\n\n**Step 2 — Review the triage.** Is the categorisation accurate?\n\n**Step 3 — For one "Action required" email**, ask Claude Code to draft a response. Read the draft carefully before approving.\n\n**Step 4 — Mandatory review:** Ask Claude: *"Review your triage analysis. What important context might you have missed? What emails might be more urgent than you categorised?"*' },

    { type: 'workshop', tag: 'BROWSER', title: 'Workshop C — Email Templates via Claude Code', content: 'Use Claude Code with Outlook MCP to build a template-based email system.\n\n**Step 1 — Identify your 3 most common email types** that follow a pattern: status updates, meeting requests, follow-ups, introductions.\n\n**Step 2 — Ask Claude Code to create email templates** for each:\n```\nCreate email templates for these recurring email types I send:\n1. [Email type 1]: [brief description of when you send it]\n2. [Email type 2]: [brief description]\n3. [Email type 3]: [brief description]\n\nFor each template:\n- Subject line with [PLACEHOLDERS]\n- Body with [PLACEHOLDERS] for variable parts\n- Tone: [your usual tone for this email type]\n```\n\n**Step 3 — Test each template** by having Claude Code draft a specific email using it.\n\n**Step 4 — Store the templates** in a Claude Code slash command or Claude Project for reuse.' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop D — Meeting Request Automation', content: 'Automate meeting request emails using Outlook MCP and Claude Code.\n\n**Step 1 — Identify a real meeting you need to schedule** this week.\n\n**Step 2 — Ask Claude Code to draft the meeting request:**\n```\nDraft a meeting request email for:\n- Recipient: [name and email]\n- Meeting purpose: [describe it]\n- Proposed times: [list 3 options]\n- Duration: [time]\n- Location/call link: [details]\n\nUse a professional but friendly tone. Include a brief agenda.\n```\n\n**Step 3 — Review the draft.** Is the tone right? Is the agenda appropriate?\n\n**Step 4 — Save as draft** in Outlook via MCP (don\'t send until you\'ve reviewed it in Outlook itself).\n\n**Step 5 — Open Outlook** and verify the draft looks correct. Send from Outlook — not from Claude Code.' },

    { type: 'quiz', question: 'Claude Code reads your emails using Outlook MCP to help you triage. What privacy consideration is most important?', options: ['Making sure Claude Code doesn\'t reply to emails automatically', 'Your email contents are processed through Anthropic\'s API — ensure this is permitted by your organisation\'s data policies and that no regulated data (client PII, financial data) appears in emails you process', 'That Claude Code doesn\'t read emails older than 30 days', 'Ensuring two-factor authentication is enabled on your email'], correct: 1, explanation: 'Email processing via Claude means email contents are sent to Anthropic\'s cloud. For many organisations, this raises compliance questions: client communication may be covered by attorney-client privilege, NDA obligations, financial regulations (GDPR, HIPAA, SEC rules), or confidentiality agreements. Check your organisation\'s AI usage policy before processing work emails through cloud AI. Personal email is generally fine; professional email requires more consideration.' },

    { type: 'quiz', question: 'Claude Code drafts an email reply using Outlook MCP. Before you send it, what is the minimum review required?', options: ['Spell-check only', 'Read the entire email: verify the recipient is correct, the content is accurate and appropriate, the tone matches your intent, and you\'re comfortable with everything it says', 'Ask Claude Code if it\'s confident in the draft', 'Have a colleague review it'], correct: 1, explanation: 'An email sent is permanent communication under your name. Minimum review: (1) correct recipient — the most important check (wrong recipient emails are a real and embarrassing incident), (2) accurate content — Claude Code may misunderstand context or include wrong information, (3) appropriate tone — especially important for sensitive topics or senior stakeholders, (4) nothing you\'re not comfortable with under your name. This review takes 60 seconds; skipping it can cause professional damage.' }
  ]
},

'8-17': {
  addMinutes: 35,
  sections: [
    { type: 'workshop', tag: 'TERMINAL', title: 'Workshop A — Teams MCP First Operations', content: 'Test the key Teams MCP operations on your real Teams account.\n\n**Step 1 — Configure Teams MCP** with Microsoft Graph credentials.\n\n**Step 2 — Test channel operations:**\n- "List my Teams channels"\n- "Show the last 10 messages in [channel name]"\n- "Find any messages mentioning me in the last 24 hours"\n\n**Step 3 — Test message search:**\n"Search for messages about \'project deadline\' in [team name] from the last week."\n\n**Step 4 — Test meeting info:**\n"What Teams meetings am I scheduled for this week?"\n\n**Step 5 — Evaluate:** Which operations were most accurate? Which were slower than expected? How does this compare to the Teams search functionality directly?' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop B — Channel Catchup Workflow', content: 'Use Teams MCP to catch up on channel activity you\'ve missed.\n\n**Step 1 — Identify channels** you haven\'t checked in more than a day.\n\n**Step 2 — Ask Claude Code:**\n```\nI\'ve been away from Teams for [time period]. For each of these channels [list them]:\n1. Summarise what was discussed\n2. Are there any decisions that were made?\n3. Any action items that involve me or my team?\n4. Any urgent items that need immediate attention?\n5. What conversations should I follow up on?\n```\n\n**Step 3 — Review the summaries.** Are they accurate? What did the AI miss?\n\n**Step 4 — For any action item identified**, draft a response or next step.\n\n**Step 5 — Compare to your normal catch-up process:** How long did AI-assisted catch-up take vs manually reading the channels?' },

    { type: 'workshop', tag: 'BROWSER', title: 'Workshop C — Meeting Insights from Teams', content: 'Extract meeting insights from your Teams meeting history.\n\n**Step 1 — Ask Claude Code to review recent Teams meetings:**\n```\nLook at my Teams meeting history for the last 2 weeks:\n1. Which meetings recurred that might be candidates for being fewer or shorter?\n2. Are there topics that appear across multiple meetings that might indicate a process problem?\n3. Which meetings had me as organiser vs attendee?\n4. What patterns do you notice in my meeting schedule?\n```\n\n**Step 2 — Review the meeting analysis.** What patterns did you already know about? What surprised you?\n\n**Step 3 — Identify one meeting** that could be eliminated, shortened, or made async.\n\n**Step 4 — Ask Claude Code** to draft a message to the relevant stakeholder proposing the change.' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop D — Teams Status and Notification Management', content: 'Use Teams MCP to manage your Teams status and notifications more intelligently.\n\n**Step 1 — Ask Claude Code to analyse your Teams notification patterns:**\n"Look at my Teams activity. What channels or people generate the most messages? Which of these are highest priority vs noise?"\n\n**Step 2 — Based on the analysis**, ask Claude Code to help you configure better defaults:\n- Which channels should be muted?\n- Which should have notifications?\n- Which keywords should trigger alerts?\n\n**Step 3 — Draft a communication** to your team about your availability and response time expectations.\n\n**Step 4 — Mandatory review:** Ask Claude: *"Review your analysis of my Teams usage. What important context did you miss that would change your recommendations?"*' },

    { type: 'quiz', question: 'You use Teams MCP to have Claude Code post a message to a team channel on your behalf. What must you review before it posts?', options: ['That the message is grammatically correct', 'The exact text that will be posted, and that it\'s appropriate for the channel\'s audience — messages posted by Claude are visible to all channel members as coming from you', 'That the channel has the right privacy settings', 'That you have the appropriate emoji reactions ready'], correct: 1, explanation: 'Messages posted to Teams channels are permanent communications to your team, recorded in message history, and attributed to you. Review: exact wording (is this what you actually want to say?), appropriate tone for the channel audience, accuracy of any technical claims or data referenced, and whether the timing is right. Posting through an MCP server doesn\'t reduce your responsibility for the content — it\'s still your professional communication.' },

    { type: 'quiz', question: 'Claude Code summarises a Teams channel and says "the team decided to delay the project deadline." Before acting on this information, what should you do?', options: ['Act on it immediately — Claude Code\'s summaries are reliable', 'Verify the decision in the original messages — Claude Code may have misread a discussion (not a decision) or missed the final conclusion of a longer thread', 'Ask a team member to confirm via email', 'Only act if Claude Code also provides message timestamps'], correct: 1, explanation: 'AI summaries of conversations can misrepresent nuance, especially around decisions. A conversation about "whether to delay" might be summarised as "decided to delay." Important decisions should be verified in the original messages — read the specific thread where the decision was made, confirm who said it and in what context. Never act on an AI-summarised decision for something consequential without verification.' }
  ]
},

'8-18': {
  addMinutes: 35,
  sections: [
    { type: 'workshop', tag: 'TERMINAL', title: 'Workshop A — Slack MCP First Operations', content: 'Test Slack MCP\'s core capabilities on your real workspace.\n\n**Step 1 — Configure Slack MCP** with a Slack API token (OAuth, with appropriate scopes).\n\n**Step 2 — Test message reading:**\n- "List channels I\'m a member of"\n- "Show the last 20 messages in #general"\n- "Find messages mentioning me in the last 48 hours"\n\n**Step 3 — Test search:**\n"Search Slack for messages about \'deployment issue\' from the last week."\n\n**Step 4 — Test file and thread operations:**\n"Show me threads with more than 5 replies in #engineering from the last 3 days."\n\n**Step 5 — Evaluate:** Which operations work smoothly? Which feel awkward? How does the MCP compare to Slack\'s own search?' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop B — Slack Catchup and Triage', content: 'Build an AI-powered Slack catchup routine.\n\n**Step 1 — Identify 3-5 Slack channels** you check daily.\n\n**Step 2 — Run a daily catchup:**\n```\nFor these Slack channels [list them], summarise what I missed in the last 24 hours:\n1. Key decisions or announcements\n2. Questions asked that no one has answered yet\n3. Issues reported or incidents flagged\n4. Anything that mentions me directly\n5. Threads I should participate in\n\nFor each finding: channel, brief summary, recommended action.\n```\n\n**Step 3 — Review the catchup summary.** Is it accurate? What important context was missed?\n\n**Step 4 — Take action on one item:** draft a Slack message response or a follow-up action.\n\n**Step 5 — Compare:** How long did this AI catchup take vs reading channels manually?' },

    { type: 'workshop', tag: 'BROWSER', title: 'Workshop C — Slack Knowledge Mining', content: 'Extract institutional knowledge from your Slack workspace.\n\n**Step 1 — Choose a technical topic** that gets discussed frequently in your Slack channels.\n\n**Step 2 — Ask Claude Code to mine Slack for knowledge about it:**\n```\nSearch across all channels for discussions about [topic] from the last 3 months. Extract:\n1. What approaches or solutions were tried?\n2. What worked and what didn\'t?\n3. Who are the subject matter experts who commented most?\n4. What is the current consensus or recommended approach?\n5. What questions are still unresolved?\n```\n\n**Step 3 — Review the knowledge extraction.** How accurate is it? Did the AI miss important context from the threads?\n\n**Step 4 — Write a brief knowledge article** based on the Slack mining. Save it somewhere searchable (Notion, Confluence, README).\n\n**Step 5 — This addresses a real pain point:** knowledge discussed in Slack often disappears from memory. Making it permanent adds long-term value.' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop D — Automated Slack Status Updates', content: 'Use Slack MCP to automate status updates and keep your team informed.\n\n**Step 1 — Identify recurring updates** you send to Slack channels: daily standups, weekly summaries, project status updates.\n\n**Step 2 — Ask Claude Code to draft a status update template:**\n```\nCreate a Slack message template for my daily standup in [channel].\nFormat: concise, clear, uses Slack formatting (bold, lists)\nSections: Yesterday\'s progress / Today\'s plan / Blockers / Notes\nTone: professional but not stiff\n```\n\n**Step 3 — Fill in the template** for today\'s actual standup.\n\n**Step 4 — Review before posting:** Read the exact message Claude Code would post. Is it accurate? Is the tone right?\n\n**Step 5 — Post the standup** via Claude Code (or copy-paste into Slack — your choice based on comfort level).\n\n**Step 6 — Evaluate:** Did the AI-assisted standup save time? Did it accurately capture your work?' },

    { type: 'quiz', question: 'Slack MCP allows Claude Code to post messages on your behalf. Which of these is the safest way to use this capability?', options: ['Enable Claude Code to post messages automatically when it has relevant updates', 'Review every message Claude Code proposes before it posts — never enable automatic posting without review', 'Only use it for DMs, not channel messages', 'Post only in private channels where fewer people see it'], correct: 1, explanation: 'Automatic posting without review is the highest-risk configuration for any communication tool MCP. Slack messages in channels are permanent, visible to potentially many people, and attributed to you. The safest workflow: Claude Code drafts the message → you read it → you confirm → it posts. This review step takes 10 seconds and prevents posting incorrect information, wrong tone, or content you didn\'t intend under your name.' },

    { type: 'quiz', question: 'You give Slack MCP access to your workspace. Which permission scope is the minimum needed to read channel messages and post replies?', options: ['Full admin access — MCPs need complete permissions to function', 'Read: channels:history, im:history. Write: chat:write — the minimum scopes for reading channels and posting messages', 'User token — MCPs should use your full user token', 'Bot token with all scopes — easier to configure than minimal permissions'], correct: 1, explanation: 'Least privilege principle applies to Slack OAuth scopes. You only need: channels:history (read messages), channels:read (list channels), im:history (read DMs if needed), chat:write (post messages). Avoid granting admin, users:read, files:write, or other scopes you don\'t need — each additional scope is a security surface. If the MCP server asks for more than this, question why.' }
  ]
},

'8-19': {
  addMinutes: 35,
  sections: [
    { type: 'workshop', tag: 'TERMINAL', title: 'Workshop A — Notion MCP First Operations', content: 'Get Notion MCP working with your real workspace.\n\n**Step 1 — Configure Notion MCP** with your Notion integration token.\n\n**Step 2 — Test basic operations:**\n- "List all databases in my Notion workspace"\n- "Show the pages in my [specific database] database"\n- "Read the content of my [page name] page"\n\n**Step 3 — Test search:**\n"Search my Notion for pages about [topic you work on]"\n\n**Step 4 — Test write operations** on a test page:\n"Create a new page in my [database] database with title \'MCP Test\' and content \'Created by Claude Code\'"\n\n**Step 5 — Verify the created page** in Notion directly.\n\n**Step 6 — Ask Claude:** "For a knowledge worker who uses Notion as their primary note-taking and project management tool, what are the 5 most valuable Notion MCP operations?"' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop B — AI-Powered Notion Knowledge Base', content: 'Use Notion MCP to build and maintain a knowledge base with AI assistance.\n\n**Step 1 — Identify a knowledge area** you manage in Notion (or would like to start managing there): documentation, research notes, project decisions.\n\n**Step 2 — Ask Claude Code to analyse and improve existing Notion content:**\n```\nReview the pages in my [Notion database]. For each page:\n1. Does it have a clear, searchable title?\n2. Is the content structured with headings?\n3. Does it have any tags/properties filled in?\n4. Is there any content that appears duplicated in other pages?\n\nRecommend a prioritised list of improvements.\n```\n\n**Step 3 — Apply improvements** to 3 pages.\n\n**Step 4 — Create a new knowledge article** via Claude Code: "Create a Notion page in [database] about [topic]. Structure it with: Overview, Key Concepts, How To, Examples, Related Pages."' },

    { type: 'workshop', tag: 'BROWSER', title: 'Workshop C — Meeting Notes to Notion', content: 'Build a workflow that automatically turns meeting notes into structured Notion pages.\n\n**Step 1 — Take a meeting transcript or notes** (real or simulated).\n\n**Step 2 — Ask Claude Code to process them into a Notion page:**\n```\nConvert these meeting notes into a structured Notion page:\n[paste your notes]\n\nStructure:\n- Date and attendees\n- Background/context\n- Discussion points (with key perspectives)\n- Decisions made\n- Action items (with owner and deadline)\n- Next meeting date\n\nCreate this as a page in my [Meeting Notes database] in Notion.\n```\n\n**Step 3 — Review the created page** in Notion. Is the structure right? Is the content accurate?\n\n**Step 4 — Compare to your current meeting notes process.** Is this faster? What did the AI miss or misrepresent?' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop D — Notion Project Dashboard', content: 'Use Notion MCP to build and maintain a project dashboard in Notion.\n\n**Step 1 — Ask Claude Code to create a project structure in Notion:**\n```\nCreate a project tracking setup in my Notion workspace for [project name]:\n1. A main project page with: overview, status, key dates, team\n2. A tasks database linked to the project\n3. A decisions log page\n4. A meeting notes database\n\nFor each, create the right properties and initial structure.\n```\n\n**Step 2 — Review each created element** in Notion.\n\n**Step 3 — Populate the first entries:** "Create the first 5 tasks in the project database based on this project description: [your description]"\n\n**Step 4 — Mandatory review:** Ask Claude: *"Review the Notion project structure you created. What important elements are missing that a project manager would include? What database relations or views would make this more useful?"*' },

    { type: 'quiz', question: 'Notion MCP can create and modify Notion pages. What is the key difference between using Notion MCP vs Notion AI (built into Notion)?', options: ['There is no difference — they use the same AI', 'Notion MCP is controlled by Claude Code in your terminal and can be part of automated workflows; Notion AI is an in-app feature triggered manually inside the Notion interface', 'Notion AI is more accurate than Notion MCP', 'Notion MCP requires a paid Notion plan; Notion AI is free'], correct: 1, explanation: 'The key difference is integration and automation potential. Notion MCP makes Notion a tool Claude Code can use in multi-step workflows — for example, read a GitHub issue → create a Notion task → add meeting notes to the right page. Notion AI is triggered from within the Notion interface and is better for in-context writing assistance. They serve different use cases and are complementary.' },

    { type: 'quiz', question: 'You use Notion MCP to have Claude Code create project pages with tasks, timelines, and stakeholder lists. Before sharing the workspace with your team, what should you verify?', options: ['That all pages have the correct formatting', 'That all content is accurate — AI may have invented details like realistic-sounding but wrong timelines, invented stakeholders, or estimated costs without basis', 'That the Notion workspace is set to team mode', 'That the pages have the right emoji icons'], correct: 1, explanation: 'AI-generated project content often looks professional and complete while containing invented specifics. Review: do the timeline dates reflect real constraints or did the AI make them up? Are the listed stakeholders actually involved in this project? Are cost or resource estimates based on actual data or AI assumptions? Content that goes to your whole team becomes shared assumptions — wrong AI-generated content can mislead an entire team.' }
  ]
},

'8-20': {
  addMinutes: 35,
  sections: [
    { type: 'workshop', tag: 'TERMINAL', title: 'Workshop A — Chain 3 MCPs on One Task', content: 'This drill chains multiple MCP servers together on a single task.\n\n**Step 1 — Ensure you have at least 3 MCP servers configured:** GitHub, Slack/Teams, and Notion or a filesystem server.\n\n**Step 2 — Give Claude Code a task that genuinely requires all 3:**\n```\n"For the highest-priority open GitHub issue in [repo], do the following:\n1. Read the issue details\n2. Search Slack for any related discussions about this issue\n3. Create a Notion page summarising: the issue, what Slack said about it, and a proposed approach"\n```\n\n**Step 3 — Watch Claude Code** move between MCP servers. Note: how does it transition between them? Does it correctly carry context from one to the next?\n\n**Step 4 — Review all 3 outputs.** Are they consistent with each other? Does the Notion page accurately represent both the GitHub issue and the Slack discussion?\n\n**Step 5 — Identify the weakest link** in this chain. Where did coordination between MCP servers work least well?' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop B — Build Your Unified Office Workflow', content: 'Design and execute a multi-MCP workflow that represents your actual work.\n\n**Step 1 — Map a real work process** that touches multiple tools: a project update workflow, a client communication workflow, a code review and deployment workflow.\n\n**Step 2 — For each step in the process**, identify: which MCP server handles it?\n\n**Step 3 — Ask Claude Code to execute the entire workflow:**\n```\nExecute this workflow using the available MCP tools:\n[describe each step and which tool it involves]\n\nFor each step: tell me what you\'re doing before doing it.\n```\n\n**Step 4 — Review each output** before Claude Code moves to the next step. Intervene if any output is wrong.\n\n**Step 5 — Mandatory end-to-end review:** At the end, ask Claude Code: *"Review the complete workflow you just executed. What could have gone wrong? What information was lost or distorted as you moved between tools?"*' },

    { type: 'workshop', tag: 'BROWSER', title: 'Workshop C — MCP Orchestration Design', content: 'Design a more complex multi-MCP orchestration for future implementation.\n\n**Step 1 — Identify your highest-value cross-tool process** — a workflow where you currently manually copy information between 4+ tools.\n\n**Step 2 — Map the ideal automated workflow:**\n- Input trigger: what starts the process?\n- Step 1: which tool, what operation, what output?\n- Step 2: which tool, what operation, what output?\n- Continue through all steps\n- Final output: what does the human see?\n\n**Step 3 — Identify the MCP servers needed** for each step.\n\n**Step 4 — Ask Claude:** *"Review this multi-MCP workflow design. What coordination challenges will arise? Where will context be lost between tools? What failure modes exist?"*\n\n**Step 5 — Decide:** Is this workflow feasible with current MCP capabilities? What would need to change to make it work?' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop D — Document Your MCP Ecosystem', content: 'Create a comprehensive map of your MCP setup and its capabilities.\n\n**Step 1 — Document your installed MCP servers:**\n```markdown\n# My MCP Ecosystem\n\n## Installed Servers\n\n### [Server Name]\n- Purpose: [what it does]\n- Tools available: [list the tools]\n- Best for: [use cases where it excels]\n- Limitations: [what it can\'t do well]\n- Access: [what credentials/permissions it uses]\n\n## Multi-Server Workflows\n### [Workflow Name]\n- Trigger: [what starts it]\n- Steps: [which servers, in what order]\n- Output: [what it produces]\n```\n\n**Step 2 — Ask Claude Code** to help complete the documentation by reading your MCP configuration.\n\n**Step 3 — Identify 3 workflows** you haven\'t automated yet but could with your current MCP setup.\n\n**Step 4 — Prioritise one** and execute it this week.' },

    { type: 'quiz', question: 'You chain GitHub MCP → Slack MCP → Notion MCP in a single Claude Code task. Claude Code reads a GitHub issue, searches Slack, and creates a Notion page. Where is coordination most likely to break down?', options: ['At the first step — GitHub MCP is always the least reliable', 'Between steps — context must be correctly transferred from one tool\'s output to the next tool\'s input, and misinterpretation accumulates across steps', 'At the last step — Notion MCP is the newest and least stable', 'There are no coordination challenges in multi-MCP workflows'], correct: 1, explanation: 'The weakest points in multi-step AI workflows are the handoffs between steps. When Claude Code reads a GitHub issue and then uses that context to search Slack, the search query must correctly capture the issue\'s intent. When Slack search results feed into Notion page creation, the summarisation must preserve important context. Errors accumulate: a subtly wrong understanding at step 1 produces a meaningfully wrong output at step 3. Review each step\'s output before allowing the workflow to continue.' },

    { type: 'quiz', question: 'Your multi-MCP workflow successfully ran but some outputs look slightly wrong. You\'re not sure which step introduced the error. What is the debugging approach?', options: ['Re-run the entire workflow and hope it\'s different', 'Add explicit review checkpoints between each step — run step 1, review output, then run step 2 with that reviewed output, then step 3', 'Only use single-MCP workflows to avoid this problem', 'Accept the slight errors — multi-MCP workflows will never be perfect'], correct: 1, explanation: 'Multi-step workflow debugging requires bisecting the problem: run step 1 alone and verify its output is correct. Then run step 2 with the verified step 1 output and check. Continue until you find where correctness breaks. Once identified, you know exactly which MCP server or transition needs fixing. Alternatively, add explicit review prompts between steps: "Here\'s what step 1 found: [output]. Does this accurately represent the situation before we proceed to step 2?"' }
  ]
},

'9-3': {
  addMinutes: 35,
  sections: [
    { type: 'workshop', tag: 'BROWSER', title: 'Workshop A — Privacy-First AI Coding Assessment', content: 'Understand the real privacy implications of different AI coding tools.\n\n**Step 1 — Ask Claude:** *"Compare the data privacy approaches of these AI coding tools: GitHub Copilot, Claude Code (Anthropic API), Tabnine, and local models (e.g., Ollama). For each: what data is sent to their servers, what is their retention policy, and when would an organisation require this option over others?"*\n\n**Step 2 — Identify your privacy requirements:** Do you work with code that contains:\n- Proprietary algorithms that cannot leave your infrastructure\n- Client data or PII in code or comments\n- Security vulnerabilities that shouldn\'t be sent to external services\n- Regulated data (healthcare, financial)\n\n**Step 3 — Map your requirements to the right tool:** For each type of code you write, which AI tool is appropriate?\n\n**Step 4 — Write a personal AI privacy policy** for your coding workflow.' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop B — Test Tabnine for Your Real Codebase', content: 'Evaluate Tabnine\'s practical value for your specific coding context.\n\n**Step 1 — Install Tabnine** in VS Code (Extensions marketplace).\n\n**Step 2 — Complete at least 30 minutes of real coding** with Tabnine active. Use it on code from your actual project, not toy examples.\n\n**Step 3 — Track these metrics:**\n- How often do you accept a Tabnine suggestion? (count)\n- How often is the suggestion exactly right? (0-10 per hour)\n- How often is it close but wrong? (needs editing)\n- How often is it completely wrong? (you ignore it)\n\n**Step 4 — Compare to another AI tool** on the same task (Claude Code or Copilot). Are the completions better or worse?\n\n**Step 5 — For privacy-sensitive code**, run a task that would normally be too sensitive for Copilot. Does Tabnine\'s local-first approach address your concern?' },

    { type: 'workshop', tag: 'BROWSER', title: 'Workshop C — Local AI Models for Privacy', content: 'Explore the option of running AI coding assistance entirely locally with no data leaving your machine.\n\n**Step 1 — Ask Claude:** *"Explain how local AI coding models work (e.g., running Ollama with CodeLlama or Mistral). What are the trade-offs vs cloud AI coding tools in terms of: code quality, speed, privacy, cost, and setup complexity?"*\n\n**Step 2 — Assess if local models are right for you:**\n- Do you have a GPU? (significant performance difference)\n- How sensitive is your code?\n- Is occasional slower/lower quality assistance acceptable?\n\n**Step 3 — If appropriate, try Ollama:**\nInstall Ollama (ollama.ai) and run: `ollama pull codellama:7b`\nConnect it to Continue.dev as a local model.\n\n**Step 4 — Compare local vs cloud** on a coding task. How much does quality differ? Is the privacy gain worth it for your use case?' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop D — Build Your Tiered AI Tool Policy', content: 'Create a tiered policy matching code sensitivity to the right AI tool.\n\n**Step 1 — Categorise your code by sensitivity:**\n- Tier 1 (Public/open source): Can use any cloud AI tool\n- Tier 2 (Internal business logic): Cloud AI acceptable with standard terms\n- Tier 3 (Proprietary algorithms/client data): Require privacy-first tool (Tabnine local, local model)\n- Tier 4 (Regulated/classified): No AI assistance without explicit approval\n\n**Step 2 — Assign each tier to a tool:**\n| Tier | AI Tool | Reason |\n|---|---|---|\n| 1 | Claude Code / Copilot | No privacy concern |\n| 2 | Claude Code | API terms acceptable |\n| 3 | Tabnine local / Ollama | Data stays local |\n| 4 | Manual / approved tool | Too sensitive |\n\n**Step 3 — Adapt the tiers** to your specific work context.\n\n**Step 4 — Share with your team** as a starting point for a team-wide AI coding policy.' },

    { type: 'quiz', question: 'Tabnine\'s main privacy claim is that it can run entirely locally. What does this mean for your code?', options: ['Your code is never analysed or used for any purpose', 'Your code (for completions) is processed only on your machine — it is not sent to Tabnine\'s servers, so it cannot be used to train models or be seen by Tabnine\'s staff', 'Your code is encrypted before being sent to Tabnine', 'Tabnine\'s local model is as accurate as cloud models'], correct: 1, explanation: 'Local processing means the code used for generating completions never leaves your machine. This addresses the primary concern with cloud AI tools: that your proprietary code becomes training data or is accessible to the vendor\'s staff. The trade-off: local models are typically less capable than the large cloud models. For sensitive codebases where privacy is the primary concern, this trade-off is often worthwhile.' },

    { type: 'quiz', question: 'Your company has a policy that "no proprietary code may be sent to third-party AI services." Which coding AI tool can you use without violating this policy?', options: ['GitHub Copilot — it has strong privacy guarantees', 'Any tool where completions are processed entirely locally without sending code to external servers', 'Claude Code — Anthropic has strong data protection', 'Any tool that signs a data processing agreement'], correct: 1, explanation: 'The policy requirement is that code cannot be sent to third-party services, regardless of their privacy guarantees or contractual protections. The only tools that definitively satisfy this are those that process code entirely locally: local models (Ollama + CodeLlama), Tabnine with local mode enabled, or any self-hosted AI model. Cloud tools like Copilot, Claude Code, and Codeium — even with strong privacy guarantees — technically send code to external servers.' }
  ]
},

'9-4': {
  addMinutes: 35,
  sections: [
    { type: 'workshop', tag: 'BROWSER', title: 'Workshop A — AI Tool Landscape Mapping', content: 'Map the complete AI coding tool landscape as it exists today.\n\n**Step 1 — Ask Claude:** *"Create a comprehensive map of the AI coding tool landscape in 2026. Include: in-editor assistants, terminal/CLI agents, AI-native IDEs, local models, and code review tools. For each category, name the leading tools."*\n\n**Step 2 — Draw your personal landscape:** On paper or a diagram tool, place each tool you\'ve encountered in this course in the right category.\n\n**Step 3 — For each tool**, mark:\n- ✓ Used (have hands-on experience)\n- ~ Tried (briefly tested)\n- ? Heard of (no experience)\n- ✗ Not relevant to my work\n\n**Step 4 — Identify your gaps:** Which tools are relevant to your work but marked ? — and what would it take to evaluate them?\n\n**Step 5 — Ask Claude:** "Based on my current tool usage [describe it], what important AI coding tools am I missing that would significantly improve my workflow?"' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop B — Build Your Optimal AI Coding Stack', content: 'Design your personal AI coding stack — the combination of tools you will actually use.\n\n**Step 1 — List your current AI coding tools** (from Part 5-9 of this course).\n\n**Step 2 — For each of your top 5 coding task types**, identify which tool is best:\n| Task | Best Tool | Why |\n|---|---|---|\n| New feature implementation | | |\n| Code review | | |\n| Debugging | | |\n| Documentation | | |\n| Learning a new library | | |\n\n**Step 3 — Identify gaps:** Are there task types that no current tool covers well?\n\n**Step 4 — Ask Claude:** *"Review my AI coding stack [paste your table]. What tools are redundant? What gaps exist? What would a senior developer in [your field] add or remove?"*\n\n**Step 5 — Finalise your stack** and commit to using it consistently for 60 days before evaluating.' },

    { type: 'workshop', tag: 'BROWSER', title: 'Workshop C — AI Tool Evaluation Framework', content: 'Build a framework for evaluating any new AI coding tool.\n\n**Step 1 — Ask Claude:** *"Design an evaluation framework for AI coding tools. What criteria should I assess to decide whether to add a new tool to my workflow? Weight each criterion by importance."*\n\n**Step 2 — Review the framework.** Add any criteria specific to your context (privacy requirements, team standardisation, cost constraints).\n\n**Step 3 — Apply the framework** to a tool you haven\'t tried yet. Fill in each criterion with your best estimate.\n\n**Step 4 — Set a decision threshold:** "I will add this tool to my stack if it scores above X across criteria Y, Z, and W."\n\n**Step 5 — Save the framework.** Use it every time you\'re considering a new AI coding tool.' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop D — AI Coding Skills Inventory and Growth Plan', content: 'Assess where you are in AI coding skills and plan your next development.\n\n**Step 1 — Rate yourself (1-5) on these AI coding skills:**\n- Using AI for code generation\n- Reviewing AI-generated code effectively\n- Prompting AI for debugging\n- Using Claude Code for autonomous tasks\n- Configuring MCP servers\n- Building CLAUDE.md for projects\n- Using custom slash commands\n- Understanding when NOT to use AI\n\n**Step 2 — Ask Claude:** *"Based on these self-ratings [paste yours], what are my 3 most impactful development areas? What resources or practice would improve each one most efficiently?"*\n\n**Step 3 — Create a 90-day growth plan:** Specific practice activities for your top 3 development areas.\n\n**Step 4 — Mandatory review:** Ask Claude: *"Review my growth plan. What are the most common mistakes people make when trying to improve in AI coding? What should I watch out for?"*\n\n**Step 5 — Schedule monthly reviews** of your progress against the plan.' },

    { type: 'quiz', question: 'You\'ve evaluated 5 AI coding tools and they all perform similarly on your main tasks. What should be the tiebreaker?', options: ['Choose the most popular one — community size means more support', 'Choose the one that integrates best with your existing workflow and requires the least context switching', 'Choose the most expensive one — higher price typically means higher quality', 'Choose the newest one — it will have the latest technology'], correct: 1, explanation: 'When tools are functionally equivalent, workflow integration is the tiebreaker. The best tool is the one you\'ll actually use consistently — and consistency comes from low friction. A slightly less capable tool that\'s integrated into your existing workflow will deliver more value than a marginally better tool that requires significant context switching. Evaluate: does it fit where you already are, or does it require building new habits around it?' },

    { type: 'quiz', question: 'The AI coding tool landscape changes rapidly with new tools releasing monthly. What is the right approach to staying current?', options: ['Constantly switch to the newest tool to stay at the cutting edge', 'Establish a stable core stack and evaluate new tools quarterly with your framework — don\'t switch unless a new tool offers meaningfully better value for your specific use cases', 'Ignore new tools until they\'ve been out for at least 2 years', 'Follow social media recommendations and switch when a tool trends'], correct: 1, explanation: 'Constant switching prevents you from developing deep proficiency with any single tool — you never learn the shortcuts, the edge cases, or the best practices. A quarterly evaluation cadence balances staying current with building expertise. When evaluating, use your criteria framework (from Workshop C) and compare new tools to your current stack on your actual tasks, not benchmark comparisons. Only switch if the improvement is meaningful and consistent.' }
  ]
}

};

function enhance(id, filePath) {
  const raw = fs.readFileSync(filePath, 'utf8');
  const lesson = JSON.parse(raw);
  const enh = enhancements[id];
  if (!enh) { console.log('SKIP '+id); return; }
  let successIdx = -1;
  for (let i = lesson.sections.length - 1; i >= 0; i--) {
    if (lesson.sections[i].type === 'callout' && lesson.sections[i].variant === 'success') {
      successIdx = i; break;
    }
  }
  const insertAt = successIdx >= 0 ? successIdx : lesson.sections.length;
  lesson.sections.splice(insertAt, 0, ...enh.sections);
  lesson.estimatedMinutes += enh.addMinutes;
  fs.writeFileSync(filePath, JSON.stringify(lesson, null, 2));
  const ws = lesson.sections.filter(s=>s.type==='workshop').length;
  const qz = lesson.sections.filter(s=>s.type==='quiz').length;
  console.log('OK '+id+' | ws:'+ws+' qz:'+qz+' mins:'+lesson.estimatedMinutes);
}

